// Irish renderings of the discrimination situations, keyed by the stable source message IDs.
export const discriminationIrish = {
  "m2257": "Inscne",
  "m2258": "Ag ceardlann deisiúcháin rothar, deir an t-eagraí gur d’fhir an seisiún agus tugann sé nó sí an áit a chuir tú in áirithe do dhuine eile.",
  "m2259": "Fiafraigh cén bunús a bhí leis an gcinneadh faoin áirithint.",
  "m2260": "Áit dheimhnithe ag an seastán deisiúcháin",
  "m2261": "Tá ceardlann phoiblí deisiúcháin rothar ar siúl sa chearnóg. Taispeánann bean deimhniú a háirithinte. Deir an t-eagraí gur d’fhir an seisiún ardleibhéil agus tairgeann sé nó sí an áit don chéad fhear eile sa scuaine. Cloiseann Garda atá ar dualgas in aice láimhe an comhrá.",
  "m2262": "Cad a d’fhiafrófá den eagraí?",
  "m2263": "Is féidir leis an áirithint dheimhnithe agus leis na focail a úsáideadh chun í a dhiúltú cabhrú lena thuiscint an raibh tionchar ag inscne an duine ar rochtain ar an gceardlann.",
  "m2264": "Fiafraigh conas a chuirtear an riail áirithinte i bhfeidhm agus an féidir leat í a fheiceáil i scríbhinn.",
  "m2265": "Má lorgaíonn tú comhairle, beidh fíricí ar leith agat le lua: an áirithint agus an chúis a tugadh duit.",
  "m2266": "Iarr ar an gcéad rannpháirtí eile a chruthú go bhfuil an áit tuillte aige.",
  "m2267": "Is faoin eagraí atá na háirithintí. Iarr míniú ar na critéir agus ar an gcaoi ar chuir an t-eagraí i bhfeidhm iad.",
  "m2268": "Conas a dhéanfá freagairt don chomhrá seo?",
  "m2269": "Éist go díreach leis an duine ar diúltaíodh a háirithint agus faigh amach cad a dúirt an t-eagraí. Bí cruinn faoi na sonraí.",
  "m2270": "Fiafraigh de gach duine cad a tharla agus seiceáil an deimhniú áirithinte.",
  "m2271": "Faigheann tú amach cén chúis a thug an t-eagraí agus tugann tú deis don rannpháirtí labhairt.",
  "m2272": "Glac le cuntas duine eile sa cheardlann in ionad labhairt leis an mbean ar diúltaíodh an áit di.",
  "m2273": "Is féidir léi féin cur síos a dhéanamh ar a háirithint agus ar an méid a dúradh léi. Tá tábhacht lena cuntas féin.",
  "m2274": "An riail a fógraíodh",
  "m2275": "Deir an póstaer gur féidir le duine ar bith a bhfuil áirithint aige nó aici freastal. Deir an t-eagraí gur athraigh sé nó sí a intinn faoi cé ba cheart freastal ar an seisiún ardleibhéil. Teastaíonn athbhreithniú ar an gcinneadh ón rannpháirtí.",
  "m2276": "Cad a chabhródh leat athbhreithniú a iarraidh?",
  "m2277": "Coinnigh cóip den riail a fógraíodh agus den áirithint. Breac síos cathain a diúltaíodh an áit duit agus na focail is cuimhin leat.",
  "m2278": "Coinnigh an deimhniú agus an póstaer, ansin iarr go ndéanfaí athbhreithniú ar an gcinneadh.",
  "m2279": "Is féidir leat na téarmaí a fógraíodh agus an míniú a fuair tú a thabhairt don soláthraí nó do chomhairleoir.",
  "m2280": "Scrios an deimhniú áirithinte nuair a thosaíonn an seisiún.",
  "m2281": "Is taifead úsáideach é an deimhniú ar d’áit agus ar na téarmaí a chonaic tú agus tú ag déanamh na háirithinte.",
  "m2282": "Cad a thaifeadfá faoin diúltú?",
  "m2283": "I dtaifead soiléir, déantar idirdhealú idir an méid a chuala an Garda, an méid a thuairiscigh an rannpháirtí agus an méid a bhí ar an bpóstaer. Cuireann IHREC eolas ar fáil faoi fhoras na hinscne.",
  "m2284": "Taifead an riail a luadh agus mínigh cá bhfaighidh an rannpháirtí eolas faoi chomhionannas.",
  "m2285": "Caomhnaíonn tú na fíricí agus cabhraíonn tú leis an rannpháirtí a roghanna a fhiosrú.",
  "m2286": "Ná taifead ach go raibh easaontas idir daoine sa scuaine.",
  "m2287": "Léiríonn na critéir áirithinte agus focail an eagraí cén fáth ar tharraing an rannpháirtí an cheist anuas. Cuir sa chuntas iad.",
  "m2288": "Inscne: gearradh isteach ar ghearánach",
  "m2289": "Feiceann tú Garda ag cur cuntas mná i leataobh agus ag éileamh go labhródh an fear atá in éineacht léi ar a son.",
  "m2290": "Mar fhinné, tabhair tacaíocht don duine chun a cuntas féin a thabhairt agus cuir i gcoinne toimhde atá bunaithe ar inscne.",
  "m2291": "“Lig don fhear é a mhíniú”",
  "m2292": "Ag deasc an stáisiúin, tosaíonn bean ag tuairisciú gur goideadh a rothar. Ní raibh an fear atá in éineacht léi i láthair nuair a goideadh é. Gearrann Garda isteach uirthi: “Cuireann mná an iomarca béime ar rudaí mar seo. Lig don fhear é a mhíniú.” Cloiseann Garda eile agus duine den phobal atá ag fanacht in aice láimhe an ráiteas. Is iad an bheirt fhinnéithe sin na róil is féidir leat a roghnú. Ní tusa an gearánach ná an Garda a rinne an ráiteas.",
  "m2293": "Is duine den phobal thú a fheiceann go díreach an chaoi a n-iompraíonn an Garda é nó í féin i leith duine eile.",
  "m2294": "Mar fhinné ón bpobal, conas a d’fhéadfá tacú léi?",
  "m2295": "Má bhraitheann tú go bhfuil sé sábháilte, féadfaidh tairiscint chiúin tacaíochta cabhrú gan smacht a bhaint di. Is í an bhean atá ag tabhairt an chuntais agus is fúithi atá sé a rá an bhfuil sí ag iarraidh ort páirt a ghlacadh.",
  "m2296": "Fiafraigh den bhean ar mhaith léi dá bhfanfá mar fhinné agus í ag tabhairt a cuntais.",
  "m2297": "Cuireann tú tacaíocht ar fáil agus fágann tú an cinneadh faoin gcuntas fúithi féin.",
  "m2298": "Iarr ar an bhfear atá in éineacht léi an tuairisc a thabhairt ionas go nglacfaidh an Garda léi.",
  "m2299": "Athdhearbhaíonn sé sin an toimhde gur cheart cuntas fir a chur in ionad chuntas na mná féin.",
  "m2300": "Is tusa an Garda a fheiceann iompar do chomhghleacaí. Ní tusa an comhghleacaí atá ag déanamh idirdhealú.",
  "m2301": "Mar Gharda atá ina fhinné, cad ba cheart duit a dhéanamh anois?",
  "m2302": "Cuir i gcoinne an ráitis agus tabhair deis don bhean labhairt arís. Faigh amach cad atá ar eolas ag gach duine i ndáiríre. Ní tomhas ar inchreidteacht duine í a inscne.",
  "m2303": "Déan idirghabháil, mínigh gur cheart éisteacht léi agus iarr uirthi leanúint ar aghaidh.",
  "m2304": "Tugann tú aghaidh láithreach ar an iompar agus tugann tú deis don ghearánach a fianaise féin a thabhairt.",
  "m2305": "Lig don fhear críochnú agus luaigh an ráiteas le do chomhghleacaí níos déanaí.",
  "m2306": "Dá bhfanfá go dtí níos déanaí, bheadh sí fós á cur ina tost anois. Tabhair deis di a cuntas féin a thabhairt láithreach.",
  "m2307": "Leithscéal agus taifead cruinn",
  "m2308": "Tugtar am don bhean críochnú. Gabhann an comhghleacaí leithscéal agus deir, os comhair an dá fhinné: “Ní gá mo chéad ráiteas a lua anois.” Fiafraíonn an bhean den fhinné ón bpobal cad a chuala sé nó sí.",
  "m2309": "Mar fhinné díreach, conas a d’fhéadfá freagairt?",
  "m2310": "Cuir síos ar na focail a chuala tú féin agus ar na gníomhartha a chonaic tú féin. Coinnigh aon nótaí ábhartha go príobháideach. Is féidir le finné díreach fiosrú le Fiosrú faoi ghearán a dhéanamh thar a cheann féin. De ghnáth, bíonn toiliú an duine eile ag teastáil chun gearán a dhéanamh thar a cheann.",
  "m2311": "Inis di cad a chuala tú, tairg cuntas fíorasach a thabhairt go príobháideach agus seiceáil an treoir d’fhinnéithe díreacha maidir le gearáin.",
  "m2312": "Cabhraíonn tú le taifead iontaofa a choinneáil agus aithníonn tú an difear idir do chuntas féin a thabhairt agus gníomhú thar a ceann.",
  "m2313": "Abair nach féidir leat an méid a chonaic tú a tharraingt anuas a thuilleadh toisc gur gabhadh leithscéal.",
  "m2314": "Ní chuireann leithscéal an t-iompar roimhe sin ar ceal agus ní choisceann sé ar fhinné díreach treoir a lorg faoi ghearán.",
  "m2315": "Mar Gharda a chonaic an t-iompar, cad ba cheart duit a dhéanamh ina dhiaidh sin?",
  "m2316": "Is féidir le leithscéal feabhas a chur ar an gcaidreamh, ach tá taifead cruinn agus aon ghníomh leantach riachtanach fós ag teastáil. Lean na nósanna imeachta cuí tuairiscithe agus maoirseachta.",
  "m2317": "Coinnigh taifead cruinn ar an ráiteas, ar an bhfreagairt agus ar an iarracht an scéal a chur ina cheart. Tarraing anuas an t-iompar tríd an nós imeachta cuí.",
  "m2318": "Caomhnaíonn tú cuntas ar ar tharla agus tugann tú aghaidh ar chuntasacht agus ar an tseirbhís a fuair an bhean.",
  "m2319": "Ós rud é gur ghabh do chomhghleacaí leithscéal, ná taifead ach an tuairisc chríochnaithe faoin rothar a goideadh.",
  "m2320": "Fágtar an t-iompar a chonaic tú ar lár dá bharr. Is dhá dhualgas ar leith iad an scéal a chur ina cheart agus taifead cruinn a dhéanamh.",
  "m2321": "Stádas sibhialta",
  "m2322": "Deir ionad pobail le custaiméir atá colscartha nach bhfuil an áirithint do bheirt aosach a fógraíodh ar fáil ach do lánúineacha pósta.",
  "m2323": "Aithin cathain a chuirtear stádas pósta nó stádas páirtnéireachta sibhialta san áireamh i gcinneadh.",
  "m2324": "Dhá thicéad don taispeántas",
  "m2325": "Chuir beirt aosach pas do bheirt in áirithe do thaispeántas, de réir an fhógra. Nuair a chuireann an freastalaí ticéad ceist orthu, deir duine acu go bhfuil sé nó sí colscartha. Diúltaíonn an freastalaí glacadh leis an bpas agus deir nach bhfuil sé ach do lánúineacha pósta. Tar éis easaontais ag an deasc, iarrtar ar Gharda atá ag an ócáid labhairt leis na custaiméirí.",
  "m2326": "Cén cheist a chuirfeadh cúis do bhuartha in iúl go soiléir?",
  "m2327": "Cuimsíonn stádas sibhialta a bheith colscartha, pósta, singil, scartha, i do bhaintreach nó i do bhaintreach fir, nó i bpáirtnéireacht shibhialta. Seiceáil ar bunaíodh cinneadh na háirithinte ar an stádas sin.",
  "m2328": "Fiafraigh cén áit a ndeirtear go gcaithfidh beirt a bheith pósta chun an pas do bheirt a úsáid.",
  "m2329": "Díríonn sé seo an aird ar choinníollacha an phas chéanna agus ar an gcúis a tugadh duit.",
  "m2330": "Fiafraigh an bhfuil ticéid níos saoire ar fáil do theaghlaigh níos mó ag an taispeántas.",
  "m2331": "Baineann an cinneadh leis an bpas do bheirt aosach a fógraíodh. Fiafraigh cén áit a luaitear an coinníoll pósta don phas sin.",
  "m2332": "Cad faoi a chuirfeá ceist ar dtús?",
  "m2333": "Faigh cuntas ar aon suaitheadh a tuairiscíodh agus éist leis an gceist ar leith faoi dhul isteach sa taispeántas.",
  "m2334": "Fiafraigh cad a tharla ag an deasc agus cén chúis a tugadh le diúltú don phas.",
  "m2335": "Is féidir leat idirdhealú a dhéanamh idir an t-iompar a tuairiscíodh duit agus an cinneadh ar mhaith leis na custaiméirí go ndéanfaí athbhreithniú air.",
  "m2336": "Iarr sonraí faoin gcolscaradh sula gcloiseann tú cad a tharla ag an deasc.",
  "m2337": "Tá an íocaíocht, an pas a fógraíodh agus an chúis a thug an freastalaí ábhartha. Is beag a chuireann sonraí príobháideacha an cholscartha leis an gcuntas seo.",
  "m2338": "Na téarmaí ar an admháil",
  "m2339": "Deir an admháil go ligeann an pas isteach aon bheirt aosach. Iarrann maoirseoir an ionaid cuntas i scríbhinn ar na custaiméirí. Ba mhaith leo a fháil amach cad ba cheart a chur ann.",
  "m2340": "Cad a scríobhfá síos?",
  "m2341": "Is le coinníollacha an phas chéanna do bheirt ba cheart comparáid a dhéanamh. Taifead na téarmaí, an cheist a cuireadh ort faoi do stádas sibhialta agus an chúis a tugadh le cead isteach a dhiúltú.",
  "m2342": "Cuir an admháil agus míniú an fhreastalaí sa chuntas.",
  "m2343": "Cabhraíonn na sonraí sin leis an maoirseoir nó le comhairleoir an cinneadh féin a scrúdú.",
  "m2344": "Ná seol ach praghas an phas.",
  "m2345": "Cabhraíonn an praghas leis an áirithint a aithint. Cuir na téarmaí a fógraíodh agus an chúis a tugadh leis an diúltú san áireamh freisin.",
  "m2346": "Conas a chuirfeá síos ar an ábhar imní?",
  "m2347": "I gcuntas cruinn, léirítear an nasc idir an diúltú agus na focail a úsáideadh faoin stádas sibhialta, agus luaitear cé a dúirt na focail sin.",
  "m2348": "Taifead cuntas na gcustaiméirí agus go ndeir an admháil “aon bheirt aosach”.",
  "m2349": "Is féidir leis an léitheoir idirdhealú a dhéanamh idir an méid a thuairiscigh na custaiméirí agus an fhoclaíocht a sheiceáil tú féin.",
  "m2350": "Abair go hachomair gur aighneas faoi phraghas an ticéid a bhí ann.",
  "m2351": "Baineann an coinníoll a luadh le pósadh. Bíonn an cuntas níos soiléire nuair a ainmnítear an cheist sin.",
  "m2352": "Stádas sibhialta: tuairisc curtha i leataobh",
  "m2353": "Baineann Garda úsáid as scaradh duine óna chéile mar chúis le tuairisc a chur i leataobh sula gcloistear na sonraí.",
  "m2354": "Déan idirdhealú idir fíricí na tuairisce agus toimhdí faoi stádas sibhialta an duine.",
  "m2355": "Sonra pearsanta á úsáid mar steiréitíopa",
  "m2356": "Tuairiscíonn duine fásta teachtaireachtaí bagracha ó chomharsa. Deir an duine go bhfuil sé nó sí scartha óna chéile agus iarrann gan dul i dteagmháil leis an iarchéile. Deir Garda: “Bíonn daoine atá scartha ag iarraidh buntáiste a fháil ar a chéile i gcónaí. Is dócha nach bhfuil tada anseo.” Níor scrúdaíodh na teachtaireachtaí fós. Cloiseann Garda eile agus finné ón bpobal an comhrá.",
  "m2357": "Mar fhinné ón bpobal, conas a d’fhéadfá cabhrú gan an cás a thógáil as lámha an duine?",
  "m2358": "Is féidir leis an duine na teachtaireachtaí a mhíniú agus a rá conas ba mhaith leis nó léi go ndéanfaí teagmháil. Is féidir leat tacú leis an duine gan sonraí príobháideacha an scartha a iarraidh.",
  "m2359": "Má tá sé sábháilte, fiafraigh den duine ar mhaith leis nó léi dá bhfanfá fad a mhínítear na teachtaireachtaí agus an freagra a fuarthas.",
  "m2360": "Díríonn an tacaíocht a thairgeann tú ar an tuairisc. Fágann tú saol príobháideach an duine as.",
  "m2361": "Fiafraigh cén chaoi ar tharla an scaradh chun a mheas an bhfuil toimhde an Gharda cóir.",
  "m2362": "Ní léiríonn an scaradh an bhfuil teachtaireachtaí an chomharsa bagrach. Cuireann ceisteanna pearsanta nach bhfuil gá leo isteach níos mó fós ar phríobháideachas an duine.",
  "m2363": "Mar Gharda atá ina fhinné, cad a chuirfeá ina cheart?",
  "m2364": "Ní hionann stádas sibhialta agus fianaise go bhfuil cuntas neamhiontaofa. Éist leis an tuairisc, scrúdaigh na teachtaireachtaí agus tabhair aird ar mhianta ábhartha an duine maidir le teagmháil.",
  "m2365": "Cuir i gcoinne an ghinearálaithe agus fill ar na teachtaireachtaí agus ar aon riachtanas sábháilteachta láithreach.",
  "m2366": "Cuireann tú eolas ábhartha in áit steiréitíopa agus tugann tú deis don duine labhairt.",
  "m2367": "Fiafraigh faoin scaradh sula gcinneann tú an bhféachfaidh tú ar na teachtaireachtaí.",
  "m2368": "Leis sin, glacann tú le toimhde gan bhunús an chomhghleacaí in áit an t-iompar a tuairiscíodh a scrúdú.",
  "m2369": "Cé atá in ann an cheist a tharraingt anuas?",
  "m2370": "Taispeánann an duine na teachtaireachtaí. Aontaíonn an comhghleacaí anois gur gá aird a thabhairt orthu ach deir leis an bhfinné ón bpobal: “Ní féidir leat gearán a dhéanamh. Ní fútsa a bhí an ráiteas.” Chuala an dá fhinné an chéad ráiteas.",
  "m2371": "Mar fhinné, cé acu ráiteas atá cruinn faoi do sheasamh?",
  "m2372": "De réir threoir Fiosrú, féadfaidh duine den phobal a chonaic an t-iompar go díreach gearán a dhéanamh. Is bealach eile é gearán a dhéanamh thar ceann duine eile agus is gnách go mbíonn toiliú an duine sin de dhíth. Ná foilsigh sonraí teagmhála príobháideacha an duine ná eolas faoina stádas sibhialta.",
  "m2373": "Breac síos na fíricí a bhaineann leis an méid a chuala tú agus léigh an treoir d’fhinnéithe díreacha.",
  "m2374": "Is féidir leat fiosrú faoi ghearán a dhéanamh mar fhinné thar do cheann féin gan a mhaíomh go bhfuil tú ag déanamh ionadaíochta ar an duine eile.",
  "m2375": "Glac leis nach bhfuil aon bhealach gearáin agat toisc nár ortsa a díríodh an ráiteas.",
  "m2376": "Tá dhá bhonn ar leith ann le gearán ó dhuine den phobal: gur díríodh an t-iompar ar an duine féin, nó gur chonaic an duine an t-iompar go díreach.",
  "m2377": "Mar Gharda a chonaic an t-iompar, cad é an chéad chéim eile ba chuí?",
  "m2378": "Fiú agus aird á tabhairt ar na teachtaireachtaí anois, is gá aghaidh a thabhairt ar an gcaoi idirdhealaitheach ar cuireadh an tuairisc i leataobh ar dtús. Taispeáin go soiléir sa taifead cad a thuairiscigh an duine agus conas a d’iompair an comhghleacaí é nó í féin.",
  "m2379": "Taifead an ráiteas agus an fhreagairt a tháinig ina dhiaidh, ansin lean na nósanna imeachta cuí tuairiscithe agus maoirseachta.",
  "m2380": "Tugann tú aghaidh ar an mbagairt a tuairiscíodh agus ar an gcóir a fuair an duine.",
  "m2381": "Glac leis go réitíonn sé ceist iompar an chomhghleacaí go hiomlán má ghlactar leis na teachtaireachtaí.",
  "m2382": "Is maith atá go bhfuil aird á tabhairt ar an tuairisc anois, ach ní mhínítear leis sin cén fáth ar cuireadh i leataobh í ar dtús.",
  "m2383": "Stádas teaghlaigh",
  "m2384": "Diúltaítear áit ar chúrsa tráthnóna do thuismitheoir toisc go nglacann an t-eagraí leis go gcuirfidh cúram leanaí isteach ar an bhfreastal.",
  "m2385": "Déan idirdhealú idir na riachtanais freastail agus toimhdí faoin tuismitheoireacht.",
  "m2386": "Áit ar an gcúrsa tráthnóna",
  "m2387": "Ag aonach foghlama pobail, iarrann duine fásta áit ar ghearrchúrsa leabharchoimeádta agus deimhníonn gur féidir leis nó léi freastal na tráthnónta atá luaite. Nuair a chloiseann an t-eagraí go bhfuil páiste ag an duine, deir sé nó sí gur rómhinic a chailleann tuismitheoirí leanaí óga seisiúin. Iarrann maor ar Gharda ag an aonach cabhrú le daoine a shuaimhniú agus an t-easaontas ag dul in olcas ag an seastán.",
  "m2388": "Conas a mhíneofá an cheist?",
  "m2389": "Áirítear ar stádas teaghlaigh, i measc nithe eile, a bheith i do thuismitheoir ar leanbh. Tá tábhacht leis an gcaoi a seiceálann soláthraí an bhfuil iarratasóir ar fáil dáiríre sula gcinneann sé cé a fhéadfaidh freastal.",
  "m2390": "Abair gur féidir leat freastal ar na seisiúin atá luaite agus fiafraigh cén riachtanas nár chomhlíon tú.",
  "m2391": "Díríonn tú ar an riachtanas freastail ábhartha agus ar an gcúis a thug an t-eagraí.",
  "m2392": "Tairg sonraí a thabhairt faoi scoil do linbh agus faoi na socruithe rialta cúraim.",
  "m2393": "Is féidir leat a dheimhniú go bhfuil tú ar fáil. Ní gá eolas mionsonraithe faoi do leanbh chuige sin.",
  "m2394": "Cén t-idirdhealú a chabhródh leat an cuntas seo a ghlacadh?",
  "m2395": "Is féidir leis an bhfoghlaimeoir an diúltú a mhíniú. Is féidir leis an eagraí aon riail freastail a mhíniú agus a rá conas a cuireadh i bhfeidhm í.",
  "m2396": "Fiafraigh conas a seiceáladh an bhféadfadh an duine freastal agus cad a dúirt an t-eagraí faoi thuismitheoirí.",
  "m2397": "Coinníonn tú an t-idirdhealú soiléir idir riachtanas praiticiúil agus toimhde faoin duine seo.",
  "m2398": "Glac leis go bhféadfadh an duine freastal ar níos lú seisiún toisc go bhfuil leanbh aige nó aici.",
  "m2399": "Deir an t-iarratasóir gur féidir leis nó léi freastal. Fiafraigh faoi chlár na seisiún agus faoin gcaoi ar measúnaíodh infhaighteacht an duine.",
  "m2400": "Tá áit fós ar fáil",
  "m2401": "Tá an t-amchlár agus na rialacha freastail mar an gcéanna do gach iarratasóir. Deimhníonn an t-eagraí go bhfuil áit fós ar fáil. Iarrann an t-iarratasóir an chúis leis an diúltú a fháil i scríbhinn.",
  "m2402": "Cad a chabhródh leat agus tú ag lorg comhairle?",
  "m2403": "Tugann an t-amchlár, an áit atá fós ar fáil agus an chúis a luadh sonraí úsáideacha don té a dhéanfaidh athbhreithniú ar an gcinneadh.",
  "m2404": "Coinnigh fógra an chúrsa agus nóta dátaithe den fhreagra a thug an t-eagraí.",
  "m2405": "Coinníonn tú taifead ar a raibh ar fáil agus ar an gcúis ar diúltaíodh an áit duit.",
  "m2406": "Fan agus bí ag brath ar do chuimhne ar an gcomhrá.",
  "m2407": "Tabharfaidh nóta gairid agus fógra an chúrsa níos mó sonraí duit le húsáid níos déanaí.",
  "m2408": "Cad is féidir leat a thairiscint ag deireadh na teagmhála?",
  "m2409": "Éist leis an imní faoin gcóir a fuair an duine agus mínigh cá bhfuil eolas le fáil faoi stádas teaghlaigh agus rochtain ar sheirbhísí.",
  "m2410": "Mínigh cá bhfuil treoir IHREC le fáil agus déan taifead ar aon iompar a bhaineann leis an gcúis ar tháinig tú.",
  "m2411": "Féadfaidh an duine eolas a lorg faoin gcinneadh maidir leis an gcúrsa, agus beidh cuntas an Gharda cruinn fós.",
  "m2412": "Abair leis an iarratasóir gurb é cúram leanaí an phríomhcheist ar cheart dó nó di a phlé.",
  "m2413": "Is í an cheist anseo ná conas a chinn an soláthraí cé a d’fhéadfadh freastal. Treoraigh an duine chuig eolas faoin gcinneadh sin.",
  "m2414": "Stádas teaghlaigh: tuismitheoir curtha ó dhoras",
  "m2415": "Diúltaíonn Garda éisteacht le tuairisc ó thuismitheoir toisc go bhfuil leanbh an tuismitheora i láthair.",
  "m2416": "Cuir i gcoinne toimhdí faoi thuismitheoirí agus déan socruithe praiticiúla chun éisteacht leis an tuairisc.",
  "m2417": "“Tar ar ais gan do leanbh”",
  "m2418": "Tagann tuismitheoir chuig an stáisiún chun damáiste do dhoras tosaigh an tí a thuairisciú tar éis ciapadh a tharla arís agus arís eile. Tá leanbh an tuismitheora, atá seacht mbliana d’aois, i láthair. Sula bhfiafraíonn Garda faoin mbaol nó faoin méid a tharla, deir sé nó sí: “Ní bhíonn gearán dáiríre ag tuismitheoirí a thugann páistí anseo. Tar ar ais gan do leanbh.” Cloiseann Garda eile agus duine den phobal an comhrá.",
  "m2419": "Mar fhinné ón bpobal, conas a d’fhéadfá cabhair a thairiscint?",
  "m2420": "Is faoin tuismitheoir atá sé a rá cén tacaíocht a bheadh úsáideach. Ní gá duit cúram an linbh a ghlacadh ort féin ná sonraí faoin gciapadh a iarraidh chun a bheith i do fhinné cabhrach.",
  "m2421": "Labhair go príobháideach leis an tuismitheoir agus tairg fanacht mar fhinné más mian leis nó léi. Fág an cinneadh faoi chúram an linbh faoin tuismitheoir féin.",
  "m2422": "Tairgeann tú tacaíocht gan cinntí a dhéanamh thar ceann an tuismitheora ná sonraí nach bhfuil gá leo a bhailiú.",
  "m2423": "Éiligh go bhfágfadh an tuismitheoir an leanbh faoi do chúram ionas gur féidir an tuairisc a ghlacadh.",
  "m2424": "Níor aontaigh an tuismitheoir leis an socrú sin. Tairg cúnamh praiticiúil agus tabhair rogha don tuismitheoir glacadh leis nó diúltú dó.",
  "m2425": "Mar Gharda atá ina fhinné, cad is gá a dhéanamh ar dtús?",
  "m2426": "Ní cúis iad freagrachtaí tuismitheora le tuairisc a chur i leataobh. Seiceáil na riachtanais láithreacha agus aontaigh ar bhealach oiriúnach chun éisteacht leis an gcuntas. Cuir leas agus príobháideachas an linbh san áireamh.",
  "m2427": "Cuir i gcoinne an diúltaithe, seiceáil an bhfuil gá le gníomh láithreach ar mhaithe le sábháilteacht, agus pléigh bealach oiriúnach leis an tuairisc a ghlacadh.",
  "m2428": "Coinníonn tú an bealach chun cabhrach ar oscailt agus smaoiníonn tú ar riachtanais phraiticiúla in áit glacadh leis nach bhfuil an gearán dáiríre.",
  "m2429": "Abair arís nach mór don tuismitheoir teacht gan an leanbh sula bhfiafróidh tú cad a tharla.",
  "m2430": "Fágann sé sin go gcinntear rochtain ar chabhair de réir steiréitíopa agus go gcuirtear moill ar sheiceáil an bhaoil a tuairiscíodh.",
  "m2431": "Príobháideachas an linbh a chosaint",
  "m2432": "Déantar socrú oiriúnach don chomhrá. Ina dhiaidh sin, deir an tuismitheoir go raibh sé níos deacra cabhair a iarraidh de bharr an ráitis. Iarrann an comhghleacaí ar an dá fhinné a rá nach raibh i gceist ach fadhb chúraim leanaí.",
  "m2433": "Cad ba cheart a chur i do chuntas mar fhinné?",
  "m2434": "Déan taifead ar an gcaoi ar cuireadh an gearán i leataobh agus ar an méid a tharla ina dhiaidh sin. Déan idirdhealú idir an méid a chonaic tú agus na tátail a bhain tú as. Cosain príobháideachas an linbh. Féadfaidh finné díreach treoir a fháil ó Fiosrú faoi ghearán a dhéanamh gan sonraí an teaghlaigh a fhoilsiú.",
  "m2435": "Coinnigh nóta príobháideach de na focail a chuala tú agus d’ord na n-imeachtaí. Ná scaip sonraí faoin leanbh.",
  "m2436": "Caomhnaíonn tú taifead ar an iompar ábhartha agus seachnaíonn tú eolas nach gá a nochtadh.",
  "m2437": "Foilsigh ainmneacha an tuismitheora agus an linbh ionas go bhféadfaidh daoine eile cinneadh a dhéanamh faoin méid a tharla.",
  "m2438": "Ní gá sonraí a phoibliú chun cuntas cruinn finné a thabhairt. D’fhéadfadh foilsiú cur isteach ar phríobháideachas an teaghlaigh.",
  "m2439": "Mar Gharda a chonaic an t-iompar, conas ba cheart duit cur síos a dhéanamh air?",
  "m2440": "Dhá ghné éagsúla den eachtra is ea an socrú praiticiúil agus an diúltú idirdhealaitheach ag an tús. Ba cheart an dá rud a lua i dtaifead cruinn.",
  "m2441": "Taifead na bunfhocail, an tionchar a thuairiscigh an tuismitheoir agus na socruithe a rinneadh. Lean an nós imeachta cuí tuairiscithe.",
  "m2442": "Déanann tú idirdhealú idir an méid a chuala tú, an méid a dúirt an tuismitheoir agus an chaoi ar tugadh deis dó nó di cabhair a fháil arís.",
  "m2443": "Ná scríobh ach “réitíodh an cheist chúraim leanaí” toisc gur tharla an comhrá ar deireadh.",
  "m2444": "Fágann sé sin ar lár an toimhde faoi thuismitheoirí agus an diúltú a chonaic tú.",
  "m2445": "Claonadh gnéasach",
  "m2446": "Diúltaítear cead isteach ag ócáid duitse agus do do pháirtí tar éis don mhaor a fháil amach gur lánúin den ghnéas céanna sibh.",
  "m2447": "Cuir d’ábhar imní in iúl agus roghnaigh duit féin cén t-eolas pearsanta ar mian leat a roinnt.",
  "m2448": "Áirithint do bheirt",
  "m2449": "Tagann beirt chuig féile bhia faoin aer le ticéid bhailí do bheirt. Tá lánúineacha eile ligthe isteach ag maor an gheata. Nuair a deir an bheirt gur páirtithe iad, deir an maor nach féidir le lánúin den ghnéas céanna teacht isteach le chéile. Glaonn comhghleacaí ar Gharda agus daoine ag tosú ag bailiú ag an ngeata.",
  "m2450": "Conas a d’fhéadfá ceist a chur faoin gcinneadh?",
  "m2451": "Féadann coinníollacha na dticéad agus focail an mhaoir cabhrú lena mheas an raibh tionchar ag claonadh gnéasach ar chead isteach. Is fútsa atá sé cén t-eolas pearsanta a roinnfidh tú.",
  "m2452": "Fiafraigh faoin riail iontrála agus faoin gcúis a bhfuil sí á cur i bhfeidhm ar bhur dticéid.",
  "m2453": "Tugann tú aghaidh go díreach ar an diúltú. Is féidir leat a roghnú arbh fhearr leat labhairt amach ón scuaine.",
  "m2454": "Iarr ar an slua ceisteanna a chur ar an maor ar bhur son.",
  "m2455": "Is féidir leat maoirseoir an ionaid a iarraidh agus áit níos príobháidí a roghnú chun an méid a tharla a mhíniú.",
  "m2456": "Conas a ghlacfá cuntas na lánúine?",
  "m2457": "D’fhéadfadh cúiseanna maithe a bheith ag daoine príobháideachas a iarraidh agus iad ag déanamh cur síos ar eachtra a bhaineann le claonadh gnéasach. Fiafraigh cad a tharla agus tabhair deis dóibh labhairt.",
  "m2458": "Tairg áit níos ciúine le labhairt agus fiafraigh cad a dúradh ag an ngeata.",
  "m2459": "Is féidir leat an cuntas ábhartha a chloisteáil agus a thaifeadadh gan iallach a chur orthu sonraí pearsanta a phlé go poiblí.",
  "m2460": "Iarr orthu a gcaidreamh a mhíniú don scuaine.",
  "m2461": "Is féidir leis an nGarda labhairt go príobháideach leis na daoine a bhí páirteach agus ceist a chur faoin riail iontrála a luadh.",
  "m2462": "Tairgeann finné cabhair",
  "m2463": "Deir cuairteoir eile gur chuala sé nó sí míniú an mhaoir agus tá an cuairteoir sásta cuntas a thabhairt. Ba mhaith leis an lánúin go ndéanfadh maoirseoir athbhreithniú ar an diúltú.",
  "m2464": "Cad a chabhródh leat beart leantach a dhéanamh?",
  "m2465": "Is féidir leis na ticéid, nóta faoin diúltú agus cuntas ó fhinné atá sásta cabhrú tacú le hiarratas ar athbhreithniú.",
  "m2466": "Coinnigh na ticéid agus glac le tairiscint an fhinné sonraí teagmhála a roinnt go príobháideach.",
  "m2467": "Caomhnaíonn tú sonraí úsáideacha agus fágann tú faoin bhfinné a roghnú cad atá sé nó sí sásta a roinnt.",
  "m2468": "Cuir sonraí teagmhála an fhinné i ngrúpa na hócáide.",
  "m2469": "Thairg an finné cuntas a thabhairt. Aontaigh leis an bhfinné conas ba cheart teagmháil a dhéanamh.",
  "m2470": "Cad ba cheart a léiriú go soiléir i do chuntas?",
  "m2471": "Taifead cé a chuala focail an mhaoir agus cá bhfuair tú gach mionsonra. Bí cúramach le heolas pearsanta.",
  "m2472": "Déan idirdhealú idir tuairisc na lánúine, cuntas an fhinné agus an méid a thug tú féin faoi deara.",
  "m2473": "Cabhraíonn sé seo le hathbhreithniú cóir agus léiríonn sé cad iad na sonraí a seiceáladh go neamhspleách.",
  "m2474": "Scríobh gur chuala gach duine ag an ngeata an míniú céanna.",
  "m2475": "Is finné amháin a thairg cuntas. Taifead an méid a deir gach duine gur chuala sé nó sí i ndáiríre.",
  "m2476": "Claonadh gnéasach: cuirtear an milleán ar an lánúin",
  "m2477": "Cuireann Garda an milleán ar lánúin chomhghnéis as an gciapadh atá siad ag iarraidh a thuairisciú.",
  "m2478": "Mar fhinné, tabhair freagra a léiríonn meas ar phríobháideachas na lánúine agus ar a gceart a scéal féin a insint mar is mian leo.",
  "m2479": "Cuirtear an milleán orthu as cabhair a lorg",
  "m2480": "Sa chearnóg, insíonn beirt bhan do Gharda gur lean duine éigin iad agus gur scairt an duine sin maslaí orthu tar éis dóibh greim láimhe a bhreith ar a chéile. Deir an Garda: “Is iad na lánúineacha comhghnéis féin a tharraingíonn an cineál sin airde orthu.” Cloiseann comhghleacaí agus duine den phobal in aice láimhe an ráiteas. Tá an té a lean an lánúin imithe.",
  "m2481": "Mar fhinné den phobal, cad a d’fhéadfá a dhéanamh má mhothaíonn tú sábháilte?",
  "m2482": "Is féidir leat tacaíocht a thairiscint agus a aithint gur caitheadh go dona leo, gan a sonraí pearsanta a athrá os comhair slua. Is faoin lánúin atá sé a roghnú an nglacfaidh siad le do chabhair agus cá labhróidh siad.",
  "m2483": "Fiafraigh den lánúin go ciúin ar mhaith leo go bhfanfá nó go dtabharfá cuntas finné ar an méid a chuala tú.",
  "m2484": "Tairgeann tú tacaíocht úsáideach gan díospóireacht phoiblí a dhéanamh dá gcaidreamh.",
  "m2485": "Iarr ar an slua a phlé ar cheart don bheirt a bheith ag siúl i ngreim láimhe.",
  "m2486": "Cuireann sé sin an milleán ar na híospartaigh arís agus nochtann sé cúrsaí pearsanta gan dul i ngleic leis an gciapadh a tuairiscíodh.",
  "m2487": "Mar an Garda a chonaic an eachtra, cad is gá duit a phlé?",
  "m2488": "Ní údar le ciapadh é claonadh gnéasach duine, agus ní laghdaíonn sé teidlíocht an duine ar chabhair le meas. Cuir i gcoinne an ráitis a chuireann an milleán ar na híospartaigh. Éist lena gcuntas agus le haon imní atá orthu fós faoina sábháilteacht.",
  "m2489": "Cuir i gcoinne an ráitis, tairg áit níos príobháidí dóibh le labhairt, agus faigh amach cad a tharla agus cén tacaíocht atá ag teastáil.",
  "m2490": "Téann tú i ngleic le hiompar do chomhghleacaí agus díríonn tú arís ar an gciapadh a tuairiscíodh.",
  "m2491": "Sula nglacann tú lena dtuairisc, abair leis an lánúin gan gean a léiriú dá chéile go poiblí.",
  "m2492": "Leis sin, déantar fadhb dá n-iompar féin agus déantar an toimhde idirdhealaitheach chéanna arís.",
  "m2493": "Baineann príobháideachas leis an bhfreagra freisin",
  "m2494": "Tairgtear áit níos ciúine don lánúin chun labhairt. Deir duine de na mná nár mhaith léi go bpléifí a n-ainmneacha ná a gcaidreamh ar líne. Deir an comhghleacaí nach raibh sa chéad ráiteas “ach magadh” agus iarrann sé ar na finnéithe dearmad a dhéanamh air.",
  "m2495": "Conas is féidir leat do chuntas a chaomhnú agus meas a léiriú ar an iarratas sin?",
  "m2496": "Is féidir nótaí príobháideacha fíorasacha a choinneáil agus leas a bhaint as na bealaí oifigiúla gearáin gan feachtas ar líne. Is féidir le finné díreach treoir a lorg maidir le gearán a dhéanamh thar a cheann féin. De ghnáth, bíonn toiliú na lánúine ag teastáil chun gníomhú thar a gceann. Ná geall go mbeidh gearán oifigiúil gan ainm.",
  "m2497": "Coinnigh cuntas príobháideach ar an ráiteas agus ar an bhfreagra. Tabhair meas dá bpríobháideachas ar líne agus seiceáil an treoir do fhinnéithe maidir le gearáin.",
  "m2498": "Caomhnaíonn tú fianaise gan cinneadh a dhéanamh thar ceann na lánúine faoi chomhroinnt a gcuid faisnéise pearsanta.",
  "m2499": "Foilsigh a n-ainmneacha chun go mbeidh cuntas an fhinné níos áitithí.",
  "m2500": "Ní gá a n-ainmneacha a scaipeadh go poiblí chun cuntas cruinn a thabhairt. Sháródh sé sin an t-iarratas a chuala tú.",
  "m2501": "Mar an Garda a chonaic an eachtra, cad ba cheart duit a dhéanamh ina diaidh?",
  "m2502": "Má thugann duine “magadh” ar ráiteas, ní shocraíonn sé sin cén tionchar a bhí aige ná ní chuireann sé deireadh le freagrachtaí tuairiscithe. Taifead an méid a dúradh, an t-ábhar imní a luadh agus an freagra a tugadh. Bí cúramach le sonraí pearsanta.",
  "m2503": "Taifead an ráiteas idirdhealaitheach agus lean an nós imeachta cuí chun an t-iompar sin a thuairisciú.",
  "m2504": "Tugann tú aird ar chuntasacht agus ar phríobháideachas araon.",
  "m2505": "Fág an ráiteas as an taifead mar deir an comhghleacaí gur ag magadh a bhí sé.",
  "m2506": "Is féidir míniú do chomhghleacaí a thaifeadadh, ach is gá fós na focail a chuala tú agus an chaoi ar caitheadh leis an lánúin a chur sa chuntas.",
  "m2507": "Aois",
  "m2508": "Fógraítear cúrsa grianghrafadóireachta do dhaoine fásta. Deirtear le hiarratasóir 67 bliain d’aois go bhfuil uasteorainn aoise leis an gcúrsa.",
  "m2509": "Fiafraigh cén cuspóir atá leis an riail aoise agus cén fhianaise atá taobh thiar di.",
  "m2510": "Teorainn aoise ag an deasc áirithintí",
  "m2511": "Téann iarratasóir 67 bliain d’aois chuig aonach pobail chun áit a chur in áirithe ar chúrsa grianghrafadóireachta lae atá fógraithe do dhaoine fásta. Deir an t-eagraí nach nglactar ach le daoine faoi bhun 60 bliain d’aois mar go gcaithfear ceamara a iompar ar shiúlóid ghearr. Ceistíonn an t-iarratasóir an riail. Tar éis easaontais, iarrtar ar Gharda atá ar dualgas in aice láimhe éisteacht leo.",
  "m2512": "Cad a d’fhéadfá a fhiafraí faoin teorainn?",
  "m2513": "D’fhéadfadh go mbeadh eisceachtaí ann ó rialacha aoise nó go gcaithfí údar a thabhairt leo. Fiafraigh cad a chaithfidh rannpháirtithe a dhéanamh ar an gcúrsa agus cén fáth ar roghnaíodh riail aoise.",
  "m2514": "Fiafraigh cén siúl agus cén trealamh atá riachtanach i ndáiríre agus cén fáth a n-úsáidtear aois mar chritéar.",
  "m2515": "Cabhraíonn sé sin leat cuspóir na rialach a thuiscint agus féachaint an bhféadann an soláthraí na riachtanais phraiticiúla a sheiceáil go díreach.",
  "m2516": "Glac leis go bhfuil an freagra dlíthiúil céanna ann do gach teorainn aoise.",
  "m2517": "Féadfaidh an comhthéacs, an chúis atá leis an riail agus an chaoi a gcuirtear i bhfeidhm í dul i bhfeidhm ar an measúnú. Iarr na sonraí a bhaineann leis an gcás seo.",
  "m2518": "Cad a sheiceálfá sula dtabharfá cuntas ar an diúltú?",
  "m2519": "Fiafraigh faoin riail aoise agus faoin gcuspóir a luadh léi. Taifead míniú an tsoláthraí gan aois an duine a úsáid mar thomhas ar a chumas.",
  "m2520": "Seiceáil cad a éilíonn an cúrsa agus cad a dúirt an t-eagraí faoi aois.",
  "m2521": "Is féidir leat an chúis a tugadh a lua agus deis a thabhairt don iarratasóir an t-ábhar imní a mhíniú.",
  "m2522": "Glac le haois an iarratasóra mar fhianaise nach féidir leis an duine páirt a ghlacadh.",
  "m2523": "Tá riachtanais phraiticiúla ag baint leis an gcúrsa. Fiafraigh fúthu agus faoi chumas an iarratasóra iad a chomhlíonadh.",
  "m2524": "Tá an tsiúlóid roghnach",
  "m2525": "Deir an clár ama clóite go bhfuil an tsiúlóid ghearr roghnach agus go mbeidh formhór na seisiún istigh. Iarrann an t-iarratasóir an riail aoise i scríbhinn.",
  "m2526": "Cad iad na sonraí a choinneofá?",
  "m2527": "Cabhraíonn an fógra faoin gcúrsa, an teorainn aoise agus an míniú faoin tsiúlóid le comhairleoir an chúis atá leis an riail a scrúdú.",
  "m2528": "Coinnigh an clár ama agus nóta dátaithe den teorainn aoise agus den mhíniú.",
  "m2529": "Tá taifead soiléir agat ar an riail agus ar an méid a iarrtar ar rannpháirtithe a dhéanamh ar an gcúrsa.",
  "m2530": "Ná coinnigh ach grianghraf de bhealach isteach an aonaigh.",
  "m2531": "Baineann clár ama an chúrsa agus míniú an eagraí leis an diúltú ar bhealach níos dírí.",
  "m2532": "Conas a chuirfeá críoch leis an gcomhrá?",
  "m2533": "Aithin an t-ábhar imní, coinnigh an dá chuntas ar riachtanais an chúrsa agus léirigh cá bhfuil eolas faoin gcomhionannas ar fáil.",
  "m2534": "Taifead an dá mhíniú agus treoraigh an t-iarratasóir chuig eolas faoi aois agus soláthar seirbhísí.",
  "m2535": "Tugann tú bealach don iarratasóir chun tuilleadh eolais a fháil faoin riail agus coinníonn tú na sonraí a theastaíonn le haghaidh athbhreithnithe.",
  "m2536": "Scríobh “riachtanais an chúrsa” mar chúis gan breathnú ar an gclár ama.",
  "m2537": "Deir an clár ama go bhfuil an tsiúlóid roghnach. Taifead an méid sin chomh maith leis an méid a dúirt an t-eagraí leat.",
  "m2538": "Aois: cuirtear cuntas i leataobh mar a bheadh mearbhall ar an duine",
  "m2539": "Caitheann Garda tuairisc ar ghoid i leataobh mar gheall ar aois an duine a thugann í, sula bhfiafraíonn sé cad a tharla.",
  "m2540": "Tacaigh le cumarsáid dhíreach gan glacadh le haois mar fhianaise ar easpa cumais.",
  "m2541": "“Is dócha go bhfuil mearbhall ort”",
  "m2542": "Tagann duine 72 bliain d’aois go dtí an stáisiún chun goid fóin a thuairisciú. Is féidir leis an duine a rá cén uair agus cá háit ar goideadh é. Deir Garda: “Ag an aois atá tú, is dócha go bhfuil mearbhall ort. Iarr ar ghaol níos óige é a insint dúinn.” Níor cuireadh aon cheist faoin ngoid fós. Cloiseann Garda eile agus finné den phobal an comhrá.",
  "m2543": "Mar fhinné den phobal, cén cúnamh a d’fhéadfá a thairiscint a fhágann an rogha ag an duine féin?",
  "m2544": "Ní chruthaíonn aois inti féin go bhfuil mearbhall ar dhuine ná go gcaithfidh duine eile labhairt thar a cheann. Tairg cabhair agus lig don duine cur síos a dhéanamh ar an ngoid.",
  "m2545": "Fiafraigh ar mhaith leis an duine go bhfanfá mar fhinné fad a thugann sé a chuntas féin.",
  "m2546": "Tairgeann tú tacaíocht gan labhairt in áit an duine mar gheall ar a aois.",
  "m2547": "Tairg an cuntas a thabhairt thar ceann an duine mar b’fhéidir gur fearr a chreidfí duine níos óige.",
  "m2548": "Déantar an toimhde chéanna arís leis sin: nach leor cuntas an duine féin mar gheall ar a aois.",
  "m2549": "Mar an Garda a chuala é seo, conas a chuirfeá tús as an nua leis an gcomhrá?",
  "m2550": "Fiafraigh cad a tharla agus an bhfuil aon tacaíocht cumarsáide ag teastáil, gan glacadh leis go bhfuil easpa cumais ann. Is féidir le gaol cuidiú más cuí agus más mian leis an duine é. Níor cheart an gaol a chur ina áit go huathoibríoch.",
  "m2551": "Cuir i gcoinne an diúltaithe atá bunaithe ar aois agus iarr ar an duine féin cur síos a dhéanamh ar an ngoid.",
  "m2552": "Bunaíonn tú an chéad chéim eile ar chuntas an duine, seachas ar a aois.",
  "m2553": "Éiligh go dtiocfadh gaol níos óige sula n-éistfidh tú leis an gcuntas.",
  "m2554": "Ní thugann aon eolas sa chás seo údar le bac den sórt sin a chur ar dhuine de bharr a aoise.",
  "m2555": "Na focail bheachta a úsáideadh",
  "m2556": "Tugann an duine cuntas soiléir. Aontaíonn an comhghleacaí anois an tuairisc a ghlacadh ach iarrann sé go scríobhfaí “tairgeadh cúnamh” mar an t-aon chur síos ar an gcéad chomhrá. Chuala an finné den phobal an dá chomhrá.",
  "m2557": "Cad a chuirfeadh le húsáideacht do chuntais mar fhinné?",
  "m2558": "I gcuntas fíorasach, luaigh na focail a dúradh agus ord na n-imeachtaí. Ná tabhair diagnóis de do chuid féin ná breithiúnas ar chumas an duine. Is féidir le Fiosrú míniú a thabhairt ar an gcaoi ar féidir le finné díreach gearán a dhéanamh.",
  "m2559": "Breac síos an ráiteas faoin aois, an méid a chonaic tú agus an t-athrú a tháinig ar an bhfreagra ina dhiaidh sin.",
  "m2560": "Má chuirtear na himeachtaí san ord ceart, is féidir leis an té a dhéanann an t-athbhreithniú idirdhealú a dhéanamh idir an diúltú i dtosach agus an chabhair a tugadh ina dhiaidh sin.",
  "m2561": "Scríobh go gcaithfidh riocht sláinte a bheith ar an duine mar gur luaigh an Garda mearbhall.",
  "m2562": "Ní fianaise ar dhiagnóis í toimhde an chomhghleacaí. Taifead an ráiteas mar ráiteas.",
  "m2563": "Cad iad na nithe ba chóir duit a thaifeadadh ar leithligh i do chuntas gairmiúil?",
  "m2564": "Taifead an diúltú idirdhealaitheach, cuntas an duine féin agus an chabhair a tugadh ina dhiaidh. Lean na nósanna imeachta tuairiscithe agus maoirseachta is infheidhme. Ná cuir síos nua ar an gcéad eachtra a cheilfeadh an méid a tharla.",
  "m2565": "Déan na codanna sin a idirdhealú sa taifead agus tarraing aird ar an iompar tríd an nós imeachta cuí.",
  "m2566": "Aithníonn tú an iarracht a rinneadh an scéal a chur ina cheart agus coinníonn tú taifead ar an bhfadhb a spreag í.",
  "m2567": "Úsáid “tairgeadh cúnamh” mar chuntas iomlán ar an gcomhrá ar fad.",
  "m2568": "Cheilfeadh sé sin an diúltú a bhí bunaithe ar aois agus thabharfadh sé leagan míthreorach d’ord na n-imeachtaí.",
  "m2569": "Creideamh reiligiúnach",
  "m2570": "Diúltaíonn oibrí deonach do d’áirithint ar rang ceoil a fógraíodh go poiblí tar éis dó a fháil amach nach bhfuil aon reiligiún agat.",
  "m2571": "Seiceáil an raibh tionchar ag creideamh reiligiúnach, nó ag easpa creidimh, ar rochtain ar sheirbhís.",
  "m2572": "An rang ceoil sa halla poiblí",
  "m2573": "Tá oibrí deonach ag seiceáil áirithintí i halla poiblí. Deir fógra na comhairle go bhfuil an rang ceoil oscailte do gach duine fásta. Fiafraíonn an t-oibrí de dhuine ar an liosta an ball d’eaglais áitiúil an duine sin. Nuair a deir an duine nach bhfuil aon reiligiún aige, diúltaíonn an t-oibrí don áirithint. Tá Garda ag cuidiú ag ócáid phoiblí taobh amuigh agus cloiseann sé duine ag lorg cabhrach.",
  "m2574": "Cén cheist a chabhródh leat an diúltú a mhíniú?",
  "m2575": "Áirítear daoine nach bhfuil aon reiligiún acu faoin bhforas a bhaineann le creideamh reiligiúnach. Cabhraíonn na coinníollacha iontrála a foilsíodh agus focail an oibrí dheonaigh leis an bhfadhb a aithint.",
  "m2576": "Fiafraigh cén riail iontrála a bhaineann le rang a fógraíodh mar rang oscailte do gach duine fásta.",
  "m2577": "Is féidir leat na coinníollacha a fógraíodh a chur i gcomparáid leis an riail ar diúltaíodh cead isteach duit dá barr.",
  "m2578": "Déan iarracht an áirithint a shocrú trí dhíospóireacht faoi chúrsaí creidimh.",
  "m2579": "Iarr ar an eagraí an cinneadh iontrála agus coinníollacha foilsithe an ranga a mhíniú.",
  "m2580": "Conas a chuirfeá ceist faoin diúltú?",
  "m2581": "Fiafraigh cad a dúradh agus fág faoin duine féin é a roghnú cé mhéad is mian leis a rá faoina chreideamh. Faigh amach cé dhéanann an cinneadh maidir le cead isteach.",
  "m2582": "Iarr ar an oibrí deonach an riail iontrála a mhíniú agus éist go díreach leis an té ar diúltaíodh cead isteach dó.",
  "m2583": "Bailíonn tú eolas faoin gcinneadh agus léiríonn tú meas ar phríobháideachas an duine.",
  "m2584": "Iarr ar an duine a chreideamh a mhíniú do gach duine atá ag fanacht.",
  "m2585": "Is é atá ábhartha ná an cheist a chuir an t-oibrí deonach agus an chaoi a ndeachaigh an freagra i bhfeidhm ar an gcinneadh. D’fhéadfadh sé a bheith níos cuí éisteacht leis an duine go príobháideach.",
  "m2586": "Seiceálann an t-eagraí an fógra",
  "m2587": "Deimhníonn an t-eagraí gur fógraíodh an rang don phobal i gcoitinne. Deir an t-oibrí deonach gur shíl sé go raibh an halla curtha in áirithe do bhaill den eaglais. Tá an duine ag iarraidh go ndéanfaí athbhreithniú ar an eachtra.",
  "m2588": "Cad a d’fhéadfá a thabhairt don eagraí?",
  "m2589": "In athbhreithniú, is féidir an fógra, an áirithint agus an chúis a tugadh ag an doras a scrúdú, agus féachaint ar thuig an t-oibrí deonach an riail iontrála.",
  "m2590": "Taispeáin deimhniú na háirithinte agus breac síos an cheist a chuir an t-oibrí deonach agus an méid a dúirt sé.",
  "m2591": "Tugann sé sin an t-eolas don eagraí a theastaíonn chun a sheiceáil cad a tharla agus conas a cuireadh an riail in iúl.",
  "m2592": "Ná déan ach cur síos ar an bhfad a bhí tú ag fanacht ag an doras.",
  "m2593": "Is cuid de chúrsa na n-imeachtaí í an tréimhse a chaith tú ag fanacht. Is í an chúis a tugadh leis an diúltú a mhíníonn an t-ábhar imní.",
  "m2594": "Cad a bheadh i dtaifead úsáideach?",
  "m2595": "Déan idirdhealú idir an méid a dheimhnigh an t-eagraí, an méid a dúirt an t-oibrí deonach agus an méid a thuairiscigh an duine.",
  "m2596": "Taifead an fógra poiblí agus cuir in iúl cé thug gach cuntas.",
  "m2597": "Feicfidh an té a léann an taifead an coinníoll a foilsíodh agus na cuntais éagsúla ar an gcaoi ar cuireadh i bhfeidhm é.",
  "m2598": "Taifead an riail iontrála mar fhíric dheimhnithe tar éis duit labhairt leis an oibrí deonach amháin.",
  "m2599": "Tá an t-eagraí freagrach as na coinníollacha foilsithe. Seiceáil a chuntas siúd chomh maith le cuntas an oibrí dheonaigh.",
  "m2600": "Creideamh reiligiúnach: tugtar neamhaird ar thuairisc",
  "m2601": "Tugann Garda neamhaird ar thuairisc faoi mhaslaí toisc gur ar dhaoine a bhí ag fágáil mosc a díríodh iad.",
  "m2602": "Aithin steiréitíopáil ar bhonn creidimh agus coinnigh an aird ar an iompar a tuairiscíodh.",
  "m2603": "Úsáidtear an áit adhartha mar leithscéal",
  "m2604": "Sa chearnóg, insíonn duine fásta do Gharda gur scairt duine éigin maslaí frith-Mhoslamacha air agus gur bhagair air agus é ag imeacht ón mosc. Deir an Garda: “Má théann tú ansin, ba chóir duit a bheith ag súil lena leithéid. Ní bheidh mé ag déileáil le gearáin faoi chreideamh.” Cloiseann Garda eile agus finné den phobal an diúltú. Ní dhearnadh measúnú fós ar an mbagairt a tuairiscíodh.",
  "m2605": "Mar fhinné den phobal, cén chabhair a d’fhéadfá a thairiscint?",
  "m2606": "Is féidir leat a aithint gur tugadh neamhaird ar an duine agus cuntas fíorasach a thairiscint mar fhinné gan iarraidh air a chreideamh a chosaint. Mura gcuala tú ach an comhrá seo, ná maígh go raibh tú i láthair nuair a rinneadh an bhagairt roimhe sin.",
  "m2607": "Tairg cuntas a thabhairt ar fhreagra an Gharda a chuala tú féin agus fiafraigh den duine ar mhaith leis go bhfanfá.",
  "m2608": "Tacaíonn tú leis an duine agus míníonn tú teorainneacha do chuid eolais féin.",
  "m2609": "Abair go bhfaca tú an chéad bhagairt freisin chun cur le neart na tuairisce.",
  "m2610": "Thabharfadh sé sin léargas bréagach ar a bhfuil ar eolas agat. Is é freagra an Gharda an t-iompar a chonaic tú féin.",
  "m2611": "Mar an Garda a bhí i láthair, cad é an freagra cuí?",
  "m2612": "Ní thugann creideamh duine ná freastal ar áit adhartha údar le cúnamh measúil a dhiúltú dó. Cuir i gcoinne an diúltaithe agus déan measúnú ar an mbagairt de réir na bhfíricí a tuairiscíodh.",
  "m2613": "Cuir i gcoinne an diúltaithe, éist leis an gcuntas ar an méid a dúradh, agus seiceáil an bhfuil cosaint nó tacaíocht ag teastáil láithreach.",
  "m2614": "Tarraingíonn tú aird arís ar an tuairisc agus ar riachtanais an duine.",
  "m2615": "Iarr ar an duine a chleachtais reiligiúnacha a phlé sula ndéanfaidh tú machnamh ar an mbagairt.",
  "m2616": "Ní coinníoll é creideamh duine chun éisteacht lena thuairisc ar mhaslaí agus ar bhagairt.",
  "m2617": "Tá teorainneacha le heolas finné chomh maith le freagrachtaí a bheith air",
  "m2618": "Éistear leis an tuairisc anois. Iarrann an comhghleacaí ar na finnéithe cur síos ar an diúltú mar mhíthuiscint faoi chreideamh. Níl eolas díreach ag an bhfinné den phobal fós ar an mbagairt a rinneadh roimhe sin.",
  "m2619": "Conas ba cheart duit an dá eachtra a idirdhealú?",
  "m2620": "Scar an méid a chuala tú ón nGarda ón méid a d’inis an duine duit faoin mbagairt roimhe sin. Is féidir le finné díreach gearán a dhéanamh faoi iompar an Gharda gan a mhaíomh go bhfaca sé an chéad eachtra.",
  "m2621": "Taifead focail an Gharda mar fhocail a chuala tú féin agus an bhagairt roimhe sin mar fhaisnéis a tugadh duit.",
  "m2622": "Is cuntas úsáideach é mar tá a chuid foinsí agus teorainneacha soiléir.",
  "m2623": "Cumaisc an dá eachtra in aon chuntas amháin agus scríobh é amhail is dá bhfaca tú gach rud.",
  "m2624": "Cheilfeadh sé sin teorainneacha do chuid eolais agus d’fhéadfadh sé an bonn a bhaint de chuntas finné a bheadh luachmhar murach sin.",
  "m2625": "Mar an Garda a chuala an comhrá, cad a dhéanfá ina dhiaidh sin?",
  "m2626": "Níor cheart go gcuirfeadh míniú a thagann níos déanaí na bunfhocail as an taifead. Caomhnaigh cuntas an duine ar an ábhar imní agus lean an nós imeachta cuí chun iompar idirdhealaitheach a thuairisciú.",
  "m2627": "Taifead an diúltú, an chaoi ar réitíodh é agus míniú an chomhghleacaí ar leithligh. Ansin tarraing aird ar an iompar ar an mbealach cuí.",
  "m2628": "Coinníonn tú taifead ar an méid a tharla gan cur síos fabhrach a chur in áit an méid a chonaic tú.",
  "m2629": "Ná taifead ach “réitíodh míthuiscint faoi chreideamh”.",
  "m2630": "Fágtar an diúltú ar lár agus ní luaitear an tuairisc ar tugadh neamhaird uirthi i dtosach.",
  "m2631": "An Lucht Siúil",
  "m2632": "Cuireann feighlí áirithint dheimhnithe seomra ar ceal nuair a fhaigheann sé amach gur den Lucht Siúil thú.",
  "m2633": "Taifead an chúis a tugadh i ndáiríre agus ceistigh toimhdí faoi phobal iomlán.",
  "m2634": "An áirithint san ionad pobail",
  "m2635": "Tá seomra curtha in áirithe agus deimhnithe ag duine den Lucht Siúil le haghaidh cruinniú teaghlaigh in ionad pobail. Deir an feighlí nach ligeann an t-ionad seomraí ar cíos do theaghlaigh den Lucht Siúil agus iarrann sé ar an duine imeacht. Tagann Garda tar éis don fheighlí argóint ag an mbealach isteach a thuairisciú.",
  "m2636": "Cad a chabhródh leat an t-ábhar imní a chur ar taifead?",
  "m2637": "Tugann an dlí cosaint ar idirdhealú ar an bhforas gur den Lucht Siúil duine. Tá tábhacht leis an gcúis a tugadh i ndáiríre nuair a dhéantar measúnú ar dhiúltú d’áirithint seomra.",
  "m2638": "Más mian leat, taispeáin deimhniú na háirithinte agus mínigh na focail a d’úsáid an feighlí.",
  "m2639": "Tugann tú cuntas sonrach ar an diúltú agus ar an gcúis ar a raibh sé bunaithe.",
  "m2640": "Tairg sonraí faoi do mhuintir a thabhairt lena chruthú gur cheart an cruinniú a cheadú.",
  "m2641": "Is iad coinníollacha na háirithinte agus an chúis a tugadh atá ábhartha. Ní theastaíonn sonraí faoi ghaolta chun iad sin a mhíniú.",
  "m2642": "Cad é an chéad rud a dhéanfá ar theacht duit?",
  "m2643": "Déan measúnú ar an méid atá ag tarlú ag an mbealach isteach i ndáiríre agus tabhair deis don duine cur síos a dhéanamh ar an diúltú.",
  "m2644": "Fiafraigh faoin iompar a tuairiscíodh, faoin áirithint agus faoi na focail a úsáideadh nuair a cuireadh ar ceal í.",
  "m2645": "Is féidir leat an chúis ar iarradh ar Gharda teacht a scrúdú agus an t-ábhar imní faoin gcóir a fuair an duine a thaifeadadh.",
  "m2646": "Glac le tuairim an fheighlí faoin teaghlach mar fhianaise ar bhaol.",
  "m2647": "Chun baol a mheas, teastaíonn fíricí a bhaineann leis an eachtra seo. Ní thugann ráiteas ginearálta faoi phobal cuntas ar iompar an duine aonair.",
  "m2648": "Tugtar an dara cúis",
  "m2649": "Iarrtar ar bhainisteoir an ionaid athbhreithniú a dhéanamh ar an áirithint. Deir an feighlí anois gur cuireadh an seomra in áirithe faoi dhó ag an am céanna. Tá an deimhniú fós ar fhón an duine a chuir an áirithint isteach.",
  "m2650": "Cad a choinneofá don athbhreithniú?",
  "m2651": "Taifead an dá mhíniú, cén uair a tugadh gach ceann acu agus ar chuala aon duine eile iad. Coinnigh an deimhniú.",
  "m2652": "Coinnigh an chéad áirithint agus cuntas dátaithe ar an dá chúis a tugadh.",
  "m2653": "Is féidir leis an té a dhéanann an t-athbhreithniú a sheiceáil ar cuireadh an seomra in áirithe faoi dhó agus an chéad mhíniú a mheas freisin.",
  "m2654": "Ná coinnigh ach an míniú is déanaí.",
  "m2655": "Tá uainiú agus foclaíocht an dá mhíniú ábhartha. Taifead an dá cheann fad atá cuimhne agat orthu.",
  "m2656": "Conas ba cheart duit plé leis an dá chuntas?",
  "m2657": "Is féidir an fhaisnéis nua a sheiceáil agus a chur leis an taifead. Tá an chéad chúis a luadh fós ábhartha don ábhar imní a tharraing an duine anuas.",
  "m2658": "Luaigh cé a thug gach míniú agus seiceáil cad a dheimhníonn taifead na háirithinte.",
  "m2659": "Coinníonn tú ord na n-imeachtaí agus déanann tú idirdhealú idir fíricí a bhfuil fianaise orthu agus maímh atá le seiceáil fós.",
  "m2660": "Cuir an chúis a tugadh níos déanaí in áit chuntas an duine a chuir an áirithint isteach.",
  "m2661": "Taifead an chéad chuntas agus an míniú a tháinig ina dhiaidh ar leithligh. Beidh an dá cheann ag teastáil chun an cás a athbhreithniú.",
  "m2662": "An Lucht Siúil: tagann comhghleacaí ar thuairim roimh éisteacht leis an tuairisc",
  "m2663": "Cuireann Garda tuairisc ó theaghlach den Lucht Siúil i leataobh ar bhonn steiréitíopa faoin bpobal.",
  "m2664": "Cuir steiréitíopa faoi ghrúpa faoi cheist agus coinnigh cuntas an duine féin.",
  "m2665": "“Is sibhse a bhíonn ag cothú trioblóide i gcónaí”",
  "m2666": "Ag ócáid phobail, tuairiscíonn duine fásta ó theaghlach den Lucht Siúil gur thug cuairteoir eile drochíde dó nó di arís agus arís eile. Agus an méid a dúradh á mhíniú, deir an duine gur den Lucht Siúil é nó í. Freagraíonn Garda: “Is é bhur bpobal atá ag cruthú fadhbanna i gcónaí. Ní rachaidh mé níos faide leis seo.” Cloiseann Garda eile agus finné ón bpobal an ráiteas. Ní fhaca ceachtar acu an drochíde a tharla níos luaithe.",
  "m2667": "Mar fhinné ón bpobal, cén freagra a d’fhéadfá a thabhairt dá mbeadh sé sábháilte?",
  "m2668": "Tacaigh leis an duine agus a scéal féin á insint aige. Ní gá labhairt ar son an phobail ar fad. Déan idirdhealú idir an méid a chonaic tú agus an drochíde roimhe sin ar insíodh duit fúithi.",
  "m2669": "Fiafraigh den duine ar mhaith leis go bhfanfá. Abair gur féidir leat cuntas a thabhairt ar fhocail an Gharda a chuala tú.",
  "m2670": "Tugann tú cúnamh praiticiúil don duine gan smacht a bhaint de ná ginearálú a dhéanamh faoin bpobal.",
  "m2671": "Abair le gach duine cén sórt daoine iad an Lucht Siúil go ginearálta chun cur in aghaidh mhaíomh an Gharda.",
  "m2672": "Má chuireann tú ginearálú eile in áit an chéad cheann, ní bheidh tú ag plé le tuairisc an duine seo ná leis an gcaoi ar caitheadh leis os do chomhair.",
  "m2673": "Mar an Garda a chonaic é seo, cad ba cheart a chur in áit an steiréitíopa?",
  "m2674": "Ní fianaise é ballraíocht den Lucht Siúil go bhfuil duine freagrach as an eachtra seo. Cuir i gcoinne an ráitis agus éist le cuntas an duine ar an eachtra féin.",
  "m2675": "Cuir an ginearálú faoi cheist. Fiafraigh den duine cad a tharla dó agus cén t-eolas is féidir a sheiceáil.",
  "m2676": "Measann tú an tuairisc de réir fhíricí an cháis féin, gan breithiúnas a bhunú ar an ngrúpa lena mbaineann an duine.",
  "m2677": "Fiafraigh faoi cháil an teaghlaigh sula n-éisteann tú leis an tuairisc faoin drochíde.",
  "m2678": "Ní ghlacann cáil ná lipéad grúpa áit na bhfíricí faoin eachtra seo.",
  "m2679": "D’athródh an cuntas dá bhfágfaí rud ar lár",
  "m2680": "Aontaíonn an comhghleacaí éisteacht leis an tuairisc ach iarrann sé nó sí ar na finnéithe an ráiteas faoin Lucht Siúil a fhágáil ar lár. Deir an duine gur baineadh dá mhuinín maidir le cabhair a lorg nuair a cuireadh an tuairisc i leataobh.",
  "m2681": "Mar fhinné ón bpobal, cad a d’fhéadfá a choinneáil ar taifead?",
  "m2682": "Taifead an méid a chuala tú agus an méid a dúirt an duine faoin tionchar a bhí aige orthu. Déan idirdhealú idir an dá rud. Is féidir le finné díreach breathnú ar threoir Fiosrú maidir le gearáin. Is ceist eile é labhairt thar ceann an teaghlaigh.",
  "m2683": "Coinnigh cuntas fíorasach ar an ráiteas agus ar an bhfreagra. Tairg go príobháideach don duine é más mian leis é a fháil.",
  "m2684": "Coinníonn tú taifead ar an iompar ábhartha agus léiríonn tú meas ar rogha an teaghlaigh maidir le tacaíocht.",
  "m2685": "Scríobh gur thug an pobal ar fad údarás duit gníomhú ar a shon.",
  "m2686": "Níor tugadh údarás den sórt sin duit. Tá luach le do chuntas mar fhinné súl gan a mhaíomh go seasann tú d’aon duine eile.",
  "m2687": "Conas a choinneofá an taifead gairmiúil cruinn iontaofa?",
  "m2688": "Cé gur aontaigh do chomhghleacaí éisteacht leis an tuairisc ina dhiaidh sin, ní cúis é sin leis an ráiteas idirdhealaitheach a fhágáil ar lár. Taifead an t-iompar agus an freagra agus lean an nós imeachta tuairiscithe cuí.",
  "m2689": "Taifead na focail a chuala tú agus an freagra a tugadh. Tarraing aird ar an iompar ar an mbealach cuí.",
  "m2690": "Fágann tú gur féidir athbhreithniú a dhéanamh ar an bhfadhb féin agus ar an ngníomh a glacadh.",
  "m2691": "Aontaigh an ráiteas a fhágáil ar lár ar eagla go gcuirfeadh sé míchompord ar an teaghlach.",
  "m2692": "Ní leigheasann cuntas míthreorach an dochar. Bí cúramach le faisnéis íogair agus tabhair cuntas cruinn ar an iompar ábhartha.",
  "m2693": "Cine",
  "m2694": "Tá ticéad bailí agat do chluiche áitiúil. Is ortsa amháin a iarrann maor do náisiúntacht a chruthú sula ligeann sé isteach thú.",
  "m2695": "Fiafraigh ar cuireadh na coinníollacha iontrála céanna i bhfeidhm ar dhaoine eile a raibh an cineál céanna ticéid acu.",
  "m2696": "Ceisteanna breise ag an gcluiche",
  "m2697": "Taispeánann duine Éireannach ticéad bailí do chluiche áitiúil. Ligeadh daoine eile a raibh an ticéad céanna acu isteach tar éis scanadh. Cloiseann an maor blas cainte an duine agus deir: “Cheapfainn ó do chuid cainte gur eachtrannach thú.” Iarrann sé cruthúnas náisiúntachta. Tagann Garda atá ar dualgas lasmuigh anonn nuair a stopann an scuaine.",
  "m2698": "Cad a chabhródh leat a thuiscint go cruinn cad atá á iarraidh ort?",
  "m2699": "D’fhéadfadh dath craicinn, náisiúntacht nó bunadh eitneach nó náisiúnta a bheith i gceist le hidirdhealú ciníoch. Seiceáil an riail iontrála a luadh agus conas a cuireadh i bhfeidhm ar lucht ticéad eile í.",
  "m2700": "Fiafraigh cén fáth a bhfuil náisiúntacht á seiceáil agus cén riail iontrála a éilíonn é.",
  "m2701": "Is féidir leat míniú soiléir a iarraidh gan níos mó eolais phearsanta a thabhairt ná mar is mian leat.",
  "m2702": "Glac leis go míneoidh an ticéad féin cén fáth ar chuir an maor an cheist sin.",
  "m2703": "Cabhraíonn an ticéad leat an áirithint a chruthú. Tá na focail bheachta agus an chúis a tugadh leis an gcoinníoll breise tábhachtach freisin.",
  "m2704": "Conas a mheasfá an méid a tharla sa scuaine?",
  "m2705": "Ní féidir náisiúntacht duine a aithint go hiontaofa óna bhlas cainte. Fiafraigh de na daoine cé na rialacha a bhain leis na ticéid agus cad a dúradh leis an lucht féachana sin.",
  "m2706": "Éist leis an duine agus seiceáil conas a ligeadh daoine a bhí in aice leis sa scuaine isteach.",
  "m2707": "Déanann tú comparáid idir daoine a raibh ticéid chomhchosúla acu agus taifeadann tú an chúis shonrach a tugadh leis an iarratas breise.",
  "m2708": "Úsáid blas cainte an duine le breith a thabhairt arbh fhiú an náisiúntacht a sheiceáil.",
  "m2709": "Tá coinníollacha an ticéid agus míniú an mhaoir ábhartha. Ní fianaise iontaofa é blas cainte go bhfuil duine i dteideal dul isteach nó nach bhfuil.",
  "m2710": "An ticéad céanna, seiceáil eile",
  "m2711": "Deimhníonn maoirseoir nár fógraíodh aon seiceáil iontrála seachas an ticéad a scanadh. Deir an maor gurbh é a chinneadh féin náisiúntacht a sheiceáil. Tá an duine ag iarraidh ar an gclub an scéal a fhiosrú.",
  "m2712": "Conas a d’fhéadfá ábhar na buartha a leagan amach?",
  "m2713": "Coinnigh an ticéad. Scríobh síos an cheist bhreise, an chúis a tugadh agus an méid a chonaic tú ag tarlú do dhaoine eile sa scuaine.",
  "m2714": "Tabhair cuntas gairid don chlub, mar aon leis an am, an ticéad agus na focail a úsáideadh.",
  "m2715": "Is féidir leis an gclub nó le comhairleoir a scrúdú ó na sonraí sin conas a cuireadh an riail iontrála i bhfeidhm.",
  "m2716": "Ná hinis don chlub ach gur stop an scuaine.",
  "m2717": "Míníonn an scuaine cén fáth ar tháinig an Garda anonn. Luaigh freisin an t-iarratas breise agus conas a seiceáladh na ticéid eile.",
  "m2718": "Cad a chuirfeá ar taifead le haghaidh athbhreithnithe?",
  "m2719": "Déan cur síos ar an gcaoi ar caitheadh le daoine a raibh ticéid chomhchosúla acu. Luaigh gurbh é an maor a thug an míniú agus gur dheimhnigh an maoirseoir an riail.",
  "m2720": "Taifead na fíricí a sheiceáil tú agus ábhar buartha an lucht féachana a labhair leat.",
  "m2721": "Cabhraíonn an taifead sin le fiosrú breise agus coinníonn sé an fhianaise agus cuntas gach duine soiléir.",
  "m2722": "Taifead gur riail de chuid an chlub a bhí sa tseiceáil bhreise gan ceist a chur ar an maoirseoir.",
  "m2723": "Deir an maoirseoir nár éiligh an club ach scanadh ticéid. Ainmnigh an duine a d’iarr an tseiceáil bhreise.",
  "m2724": "Cine: roghnaíonn comhghleacaí duine ar leith",
  "m2725": "Feiceann tú Garda ag moladh mála duine a chuardach de bharr chine an duine, gan eolas sonrach a bheith aige faoin duine féin.",
  "m2726": "Déan idirdhealú idir steiréitíopa grúpa agus forais dhlíthiúla. Tabhair freagra mar fhinné.",
  "m2727": "Steiréitíopa á chur i láthair mar fhoras le cuardach",
  "m2728": "Ag stad bus, deir Garda le duine fásta Dubh a mhála a oscailt ionas gur féidir drugaí a chuardach ann. Deir an Garda lena chomhghleacaí i gcluas an duine agus finné ón bpobal: “Is mó an seans go mbíonn drugaí ar dhaoine den chine sin.” Ní luann an Garda aon ní a chonaic sé ná aon eolas eile a nascann an duine seo le drugaí. Is féidir leat imirt mar an comhghleacaí nó mar an finné ón bpobal.",
  "m2729": "Mar fhinné ón bpobal, cad a d’fhéadfá a dhéanamh dá mbeadh sé sábháilte?",
  "m2730": "Is féidir leat tairiscint fanacht mar fhinné agus nóta a dhéanamh de na focail a úsáideadh gan bac fisiciúil a chur ar an nGarda. Ní gá dul in aghaidh an Gharda go díreach chun cuntas a choinneáil ná chun comhairle a lorg níos déanaí maidir le gearán.",
  "m2731": "Fan achar sábháilte uathu agus fiafraigh den duine ar mhaith leis go bhfanfá mar fhinné.",
  "m2732": "Tairgeann tú tacaíocht gan an eachtra a ghlacadh ort féin ná achrann fisiciúil a chothú.",
  "m2733": "Glac leis nach bhfógródh Garda cuardach drugaí mura mbeadh forais bhailí aige leis.",
  "m2734": "Bhí an ráiteas a chuala tú bunaithe ar chine. Ní cruthúnas ar fhorais dhlíthiúla é cuardach a fhógairt.",
  "m2735": "Mar an Garda a chuala an ráiteas, cad is gá a dhéanamh sula dtéitear ar aghaidh leis an gcuardach?",
  "m2736": "Ní thugann cine forais chun duine ar leith a chuardach le haghaidh drugaí. Ní mór cúis réasúnach a bheith ann chun an chumhacht faoi alt 23 a fheidhmiú. Cuir i gcoinne an steiréitíopa agus cuir an cuardach atá beartaithe ar fionraí fad a dhéantar an t-eolas atá ar fáil agus an bunús dlíthiúil a sheiceáil.",
  "m2737": "Cuir an cuardach atá molta ar sos. Cuir an ráiteas faoi cheist agus fiafraigh cén t-eolas sonrach atá mar bhunús leis an gcumhacht sin a fheidhmiú.",
  "m2738": "Téann tú i ngleic leis an roghnú idirdhealaitheach agus seiceálann tú an bunús reachtúil sula ndéantar an cuardach.",
  "m2739": "Lig don chuardach dul ar aghaidh ar dtús agus úsáid aon ní a aimsítear chun an bunchinneadh a chosaint.",
  "m2740": "Má aimsítear rud níos déanaí, ní chruthaíonn sé sin go cúlghabhálach na forais a bhí in easnamh nuair a moladh an cuardach.",
  "m2741": "Ní athraíonn an toradh an bhunchúis",
  "m2742": "Cuirtear an cuardach ar sos. Ní luann an comhghleacaí aon fhoras eile agus insítear don duine go bhfuil cead aige imeacht. Iarrann an comhghleacaí ar na finnéithe “gnáthobair” a chur ar an taifead mar chúis an chuardaigh in ionad an ráitis chiníoch a chuala siad beirt.",
  "m2743": "Cad ba cheart a bheith i do chuntas mar fhinné?",
  "m2744": "Déan idirdhealú idir an chaoi ar roghnaíodh an duine, an chúis a tugadh agus an cinneadh a rinneadh ina dhiaidh sin. Féadfaidh taighde pobail comhthéacs a thabhairt ach ní féidir leis toradh an ghearáin aonair seo a chinneadh. Mínítear i dtreoir Fiosrú d’fhinnéithe díreacha conas is féidir le duine den phobal gearán a dhéanamh.",
  "m2745": "Nótáil na focail a chuala tú, an cuardach a moladh agus gur cuireadh ar sos é sular imigh an duine.",
  "m2746": "Léiríonn ord na n-imeachtaí an chúis a tugadh ag an am agus an gníomh a lean í.",
  "m2747": "Taifead go ndearnadh cuardach iomlán mar chuirfeadh sé sin le neart an ghearáin.",
  "m2748": "Sa scéal seo cuireadh an cuardach ar sos. Is tábhachtaí cruinneas ná cuma níos tromchúisí a chur ar an eachtra.",
  "m2749": "Conas a d’fhreagrófá don iarratas an fhoclaíocht a athrú?",
  "m2750": "Ná cuir lipéad neodrach in áit cúise idirdhealaithí arbh fhinné thú uirthi. Taifead an cuardach a moladh, an fáth ar cuireadh ina choinne agus an méid a tharla ansin. Lean na nósanna imeachta tuairiscithe cuí.",
  "m2751": "Taifead na focail a dúradh agus an idirghabháil a rinneadh, agus tuairiscigh an t-iompar tríd an nós imeachta cuí.",
  "m2752": "Cinntíonn tú go léiríonn an taifead fíorbhunús an ghnímh a moladh.",
  "m2753": "Glac leis an bhfoclaíocht “gnáthobair” toisc nach ndearnadh an cuardach.",
  "m2754": "Cuireann stop a chur leis an gcuardach cosc ar thuilleadh dochair. Ní thugann sé údar le cuntas míthreorach.",
  "m2755": "Míchumas",
  "m2756": "Ag stáisiún Gardaí, is mian le duine Bodhar damáiste dá rothar a thuairisciú. Iarrann sé modh cumarsáide atá inrochtana dó.",
  "m2757": "Aontaígí ar bhealach le cumarsáid dhíreach a dhéanamh agus seiceálaigí an n-oibríonn sé.",
  "m2758": "Ag glacadh le tuairisc sa stáisiún",
  "m2759": "Tagann duine Bodhar agus cara leis chuig stáisiún Gardaí chun damáiste do rothar an duine a thuairisciú. Tá an fáiltiú gnóthach agus cuireann an Garda na ceisteanna ar an gcara. Taispeánann an duine nóta a iarrann ar an nGarda labhairt leis féin go díreach agus na ceisteanna a scríobh síos.",
  "m2760": "Conas a d’fhéadfá a mhíniú cad a chuideodh leat páirt a ghlacadh?",
  "m2761": "Úsáideann daoine modhanna éagsúla cumarsáide. Is féidir leat a mhíniú cad a oireann duit agus a roghnú an dteastaíonn cabhair do chompánaigh uait.",
  "m2762": "Iarr ar an nGarda na chéad cheisteanna a scríobh síos agus ligean duit an tuairisc a léamh ar ais.",
  "m2763": "Is féidir leat freagra a thabhairt go díreach agus cruinneas an chuntais a sheiceáil.",
  "m2764": "Fág faoi do chara na ceisteanna go léir a fhreagairt, fiú mura bhfaca sé cad a tharla.",
  "m2765": "Is féidir leat ceisteanna a iarraidh i bhfoirm a oireann duit. Féadfaidh do chara cabhrú leat más mian leat.",
  "m2766": "Conas a thosófá ag glacadh na tuairisce?",
  "m2767": "Labhair leis an duine féin, fiafraigh cén modh cumarsáide a oibríonn dó agus seiceáil gur féidir leis a thuiscint agus a scéal a insint.",
  "m2768": "Scríobh síos na ceisteanna mar a iarradh ort agus seiceáil an oibríonn an socrú.",
  "m2769": "Is féidir leat an tuairisc a fháil ón duine féin agus an t-eolas a sheiceáil in éineacht leis.",
  "m2770": "Ná labhair ach leis an gcara, mar a rinne tú go dtí seo.",
  "m2771": "D’iarr an duine cumarsáid dhíreach. Úsáid an modh a roghnaigh sé agus fiafraigh ar mhaith leis cabhair óna chara.",
  "m2772": "Tá tuilleadh tacaíochta de dhíth le cuntas níos iomláine a thabhairt",
  "m2773": "Is leor an scríbhneoireacht chun na sonraí teagmhála bunúsacha a thabhairt. Deir an duine gurbh fhearr leis ateangaire Theanga Chomharthaíochta na hÉireann a bheith i láthair don chuntas mionsonraithe. Féachann an Garda conas an chéad chruinniú eile a shocrú.",
  "m2774": "Cén socrú a d’fhéadfá a iarraidh ar an nGarda a dhéanamh leat?",
  "m2775": "D’fhéadfadh do riachtanais inrochtaineachta athrú de réir mar a éiríonn an comhrá níos casta. Aontaígí ar mhodh teagmhála agus ar bhealach chun an tuairisc iomlán a thabhairt agus a sheiceáil.",
  "m2776": "Fiafraigh conas an chéad chruinniú eile a shocrú agus aontaígí ar mhodh teagmhála a oireann duit.",
  "m2777": "Is féidir leat pleanáil conas do chuntas a thabhairt agus ceisteanna a chur faoin gcéad chéim eile.",
  "m2778": "Glac leis gur tuairisc iomlán í nuair a bheidh na sonraí teagmhála scríofa síos.",
  "m2779": "Tá an cuntas iomlán fós le tabhairt. Aontaígí ar an am agus ar an modh chun é a thabhairt.",
  "m2780": "Cad ba cheart a dhéanamh sula gcuirtear deireadh leis an gcomhrá?",
  "m2781": "Seiceáil cén tacaíocht atá de dhíth, cad is féidir a shocrú agus conas scéala a thabhairt don duine ar bhealach a oireann dó.",
  "m2782": "Taifead an t-iarratas, seiceáil conas an tacaíocht a eagrú agus aontaígí ar shocrú inrochtana don chéad teagmháil eile.",
  "m2783": "Fanann an duine páirteach agus bíonn taifead soiléir ann ar a riachtanais chumarsáide agus ar na chéad chéimeanna eile.",
  "m2784": "Glac leis go n-oibreoidh an modh a úsáideadh do na sonraí teagmhála do gach cuid den tuairisc.",
  "m2785": "Tá riachtanas eile luaite ag an duine don chuntas mionsonraithe. Pléigh na socruithe leis.",
  "m2786": "Míchumas: tacaíocht chumarsáide á diúltú",
  "m2787": "Diúltaíonn Garda d’íospartach Bodhar a d’iarr tacaíocht chumarsáide chun coir a thuairisciú.",
  "m2788": "Cuir cumarsáid inrochtana ar fáil arís gan iarraidh ar fhinné ón bpobal cuntas íogair a ateangaireacht.",
  "m2789": "“Mura gcloiseann tú mé, ní féidir liom cabhrú leat”",
  "m2790": "Tagann duine fásta Bodhar chuig an stáisiún chun ionsaí a thuairisciú. I dteachtaireacht scríofa iarrann sé ateangaire Theanga Chomharthaíochta na hÉireann le haghaidh an chuntais mhionsonraithe. Léann Garda í agus deir: “Mura gcloiseann tú mé, ní féidir liom cabhrú leat.” Feiceann Garda eile agus finné ón bpobal an t-iarratas agus an diúltú.",
  "m2791": "Mar fhinné ón bpobal, cén tacaíocht a d’fhéadfá a thairiscint?",
  "m2792": "Fiafraigh den duine cad ba mhaith leis ar bhealach atá sothuigthe dó. Ní chiallaíonn sé gur ateangaire oiriúnach thú ach tú a bheith i láthair. Ná glac leis go bhfuil cead agat cuntas príobháideach an duine a fháil.",
  "m2793": "Scríobh teachtaireacht ghairid a fhiafraíonn den duine ar mhaith leis go bhfanfá mar fhinné agus tacaíocht chumarsáide á socrú.",
  "m2794": "Tairgeann tú tacaíocht inrochtana gan smacht a fháil ar an gcuntas ná ról an ateangaire a ghlacadh ort féin.",
  "m2795": "Tairg cuntas mionsonraithe an ionsaithe a ateangaireacht cé nach bhfuil Teanga Chomharthaíochta na hÉireann agat.",
  "m2796": "Ní bheadh an chumarsáid sin iontaofa agus d’fhéadfadh sé eolas íogair a nochtadh gan ghá.",
  "m2797": "Mar an Garda a chonaic é seo, cén freagra ba cheart a thabhairt?",
  "m2798": "Cuir i gcoinne an diúltaithe, seiceáil riachtanais láithreacha an duine ar bhealach inrochtana agus eagraigh tacaíocht chuí ateangaireachta. Baineann alt 22 le cumarsáid inrochtana agus cúnamh ateangaireachta, faoi réir na n-eisceachtaí reachtúla is infheidhme. Socraigh cúnamh cuí a luaithe is indéanta; ná geall go mbeidh ateangaire ar fáil láithreach bonn, aghaidh ar aghaidh.",
  "m2799": "Cuir i gcoinne an diúltaithe. Seiceáil na riachtanais láithreacha ar bhealach inrochtana agus eagraigh an tacaíocht chumarsáide a iarradh tríd an bpróiseas cuí.",
  "m2800": "Téann tú i ngleic leis an mbac cumarsáide agus le diúltú do chomhghleacaí gan brath ar dhuine den phobal nach bhfuil cáilithe.",
  "m2801": "Cuir na ceisteanna arís de ghuth níos airde agus lean ort leis an gcuntas mionsonraithe.",
  "m2802": "Ní fhreastalaíonn guth níos airde ar an riachtanas a mhínigh an duine. Tacaíocht ateangaireachta a d’iarr sé.",
  "m2803": "Ní hionann an chéad teagmháil agus an cuntas iomlán",
  "m2804": "Seiceáiltear riachtanais láithreacha an duine ar bhealach a thuigeann sé, agus tá ateangaireacht á socrú. Deir an comhghleacaí gur leor na sonraí teagmhála a scríobhadh síos mar chuntas iomlán ar an ionsaí agus nach gá an diúltú a thaifeadadh.",
  "m2805": "Cad ba cheart duit a rá faoin méid arbh fhinné thú air?",
  "m2806": "Déan idirdhealú idir an t-iarratas ar thacaíocht, na sonraí teagmhála tosaigh agus an cuntas mionsonraithe nár tugadh os do chomhair. Is féidir le finné súl comhairle a lorg faoi ghearán maidir le freagra an Gharda gan cuntas príobháideach an duine ar an ionsaí a aithris.",
  "m2807": "Taifead an t-iarratas agus an diúltú a chonaic tú. Ná maígh gur glacadh an cuntas iomlán i do láthair.",
  "m2808": "Is faoin mbac cumarsáide agus faoin bhfreagra a chonaic tú atá d’fhianaise.",
  "m2809": "Sínigh cuntas a deir gur aistríodh tuairisc iomlán an ionsaithe duit trí ateangaire.",
  "m2810": "Ní dhearna tú ateangaireacht ná ní bhfuair tú an cuntas iomlán. Ná deimhnigh gur tharla rud nár tharla.",
  "m2811": "Mar an Garda a chonaic é seo, cén obair leantach ar cheart duit a chinntiú?",
  "m2812": "Coinnigh an chéad teagmháil agus an cuntas iomlán ar leithligh, taifead an diúltú agus an freagra go cruinn, agus lean suas na socruithe cumarsáide agus na freagrachtaí tuairiscithe.",
  "m2813": "Taifead a theoranta a bhí an chéad teagmháil. Cuir na socruithe ateangaireachta i gcrích agus tarraing aird ar an diúltú idirdhealaitheach ar an mbealach cuí.",
  "m2814": "Coinníonn tú taifead cruinn agus cinntíonn tú gur féidir leis an duine an cuntas mionsonraithe a thabhairt fós.",
  "m2815": "Dún an cás mar “chumarsáid curtha i gcrích” mar go bhfuarthas na sonraí teagmhála i scríbhinn.",
  "m2816": "Ní hionann sonraí teagmhála agus an cuntas mionsonraithe a theastaigh ón duine a thabhairt le tacaíocht.",
  "m2817": "Cúnamh tithíochta",
  "m2818": "Diúltaíonn gníomhaire ligin ligean duit an t-árasán a fheiceáil ag an am a chuir tú in áirithe, tar éis dó nó di a fháil amach go bhfaigheann tú an Íocaíocht Cúnaimh Tithíochta (HAP).",
  "m2819": "Déan idirdhealú idir an cheist lóistín agus freagra an Gharda ag an réadmhaoin.",
  "m2820": "Diúltaíodh duit an t-árasán a fheiceáil",
  "m2821": "Tagann duine chuig coinne dheimhnithe chun árasán ar cíos príobháideach a fheiceáil agus luann sé nó sí go bhfaigheann sé nó sí an Íocaíocht Cúnaimh Tithíochta (HAP). Deir an gníomhaire ligin go bhfuil an t-árasán ar fáil, ach diúltaíonn sé é a thaispeáint d’iarratasóirí a fhaigheann HAP. Glaoitear ar Gharda tar éis achrann lasmuigh den árasán a thuairisciú.",
  "m2822": "Cad a chabhródh leat eolas a fháil faoin diúltú?",
  "m2823": "Baineann foras idirdhealaithe an chúnaimh tithíochta le soláthar lóistín. Cuidíonn an deimhniú ar an gcoinne féachana agus an chúis a thug an gníomhaire leis an gceist a shoiléiriú.",
  "m2824": "Iarr ar an ngníomhaire an chúis a dheimhniú agus coinnigh an deimhniú a fuair tú ar an gcoinne.",
  "m2825": "Is féidir leat an deimhniú agus an chúis ar diúltaíodh an choinne féachana duit a thabhairt do chomhairleoir.",
  "m2826": "Iarr ar an nGarda an t-árasán a leithdháileadh ort.",
  "m2827": "Is féidir leis an nGarda éisteacht le cuntas ar an méid a tharla ag an áitreabh. Is féidir le IHREC eolas a thabhairt faoi chomhionannas i gcúrsaí cóiríochta agus faoi na chéad chéimeanna eile a d’fhéadfaí a ghlacadh.",
  "m2828": "Cad ba cheart duit a fháil amach nuair a thagann tú ar an láthair?",
  "m2829": "Déileáil le haon cheist láithreach maidir le sábháilteacht nó iompar agus éist leis an gcuntas faoi dhiúltú na coinne. Is féidir an cinneadh tithíochta a ardú tríd an bpróiseas comhionannais ábhartha.",
  "m2830": "Fiafraigh cad a tharla lasmuigh agus taifead an chúis a deir an t-iarratasóir a tugadh leis an diúltú.",
  "m2831": "Is féidir leat an achrann a tuairiscíodh a mheas agus cabhrú leis an iarratasóir teacht ar eolas ábhartha faoin gcomhionannas.",
  "m2832": "Abair leis an ngníomhaire cén t-iarratasóir a chaithfear a roghnú don tionóntacht.",
  "m2833": "Is cuid den phróiseas lóistín é roghnú an tionónta. Faigh amach cad a tharla ag an bhfoirgneamh agus mínigh cá bhfaighidh an t-iarratasóir comhairle faoin diúltú.",
  "m2834": "Tagann an chúis i scríbhinn",
  "m2835": "Seolann an gníomhaire teachtaireacht ina ndeimhnítear go bhfuil an t-árasán fós ar fáil agus nach mbreithneoidh an ghníomhaireacht ach daoine nach bhfaigheann HAP. Fiafraíonn an t-iarratasóir cá bhfaighidh sé nó sí eolas faoi na roghanna atá ann.",
  "m2836": "Cad a thabharfá leat agus comhairle á lorg agat?",
  "m2837": "Coinnigh an teachtaireacht, an fógra agus deimhniú na coinne. Mínítear i dtreoir IHREC maidir le cúnamh tithíochta na cearta ábhartha agus cá bhfuil comhairle le fáil.",
  "m2838": "Coinnigh cóip den teachtaireacht agus an dáta léi. Iarr eolas faoi idirdhealú ar fhoras cúnaimh tithíochta.",
  "m2839": "Cabhraíonn an chúis scríofa agus na dátaí leis an gcomhairleoir an fhadhb lóistín a thuiscint.",
  "m2840": "Ná coinnigh ach nóta gur tháinig Garda ar an láthair.",
  "m2841": "Baineann teachtaireacht an ghníomhaire agus sonraí na coinne go díreach leis an gcúis ar diúltaíodh ligean don duine an t-árasán a fheiceáil.",
  "m2842": "Conas a d’fhéadfá an chéad chéim eile a mhíniú?",
  "m2843": "Is dhá ní ar leith iad teacht an Gharda ar an láthair agus gearán faoin lóistín. Cuidigh leis an duine an t-eolas agus an tacaíocht a bhaineann le gach ceann a aimsiú.",
  "m2844": "Mínigh cad a thaifead tú agus taispeáin don duine cá bhfuil treoir IHREC maidir le cúnamh tithíochta.",
  "m2845": "Tá an treoir faoin lóistín ar fáil don iarratasóir agus tá a fhios aige cad a thaifead an Garda faoin eachtra.",
  "m2846": "Tabhair le tuiscint gur ionann taifead an Gharda ar theacht ar an láthair agus gearán comhionannais a chomhdú.",
  "m2847": "Tá próiseas ar leith ag baint le gearán comhionannais. Treoraigh an t-iarratasóir chuig eolas faoin bhfadhb lóistín a ardú.",
  "m2848": "Cúnamh tithíochta: comhghleacaí ag glacadh taoibh",
  "m2849": "Nuair a dhiúltaítear do dhuine árasán a fheiceáil, labhraíonn Garda go dímheasúil faoin iarratasóir a fhaigheann HAP agus ní éisteann an Garda le cuntas ar ar tharla.",
  "m2850": "Déan idirdhealú idir idirdhealú a d’fhéadfadh a bheith i gceist le lóistín agus iompar an Gharda féin.",
  "m2851": "Coinne féachana á diúltú agus Garda nach n-éisteann",
  "m2852": "Lasmuigh d’árasán, diúltaíonn gníomhaire do dhuine an t-árasán a fheiceáil ag am coinne a bhí deimhnithe, toisc go bhfaigheann an t-iarratasóir an Íocaíocht Cúnaimh Tithíochta (HAP). Tagann Gardaí tar éis achrann a thuairisciú. Deir Garda amháin: “Má tá HAP á fháil agat, ní féidir leat a bheith ag súil leis an gcóir chéanna. Ní éistfidh mé leis seo.” Cloiseann Garda eile agus duine den phobal atá ag fanacht lena choinne féin an ráiteas.",
  "m2853": "Mar fhinné ón bpobal, cad a d’fhéadfá a thairiscint dá mbeadh sé sábháilte?",
  "m2854": "Is féidir leat cuntas a thabhairt ar dhiúltú an ghníomhaire agus ar fhreagra an Gharda, a mhéid is a chonaic nó a chuala tú féin iad. Is faoin iarratasóir atá sé glacadh le tacaíocht. Ní ag an bhfinné atá sé an tionónta a roghnú.",
  "m2855": "Fiafraigh den iarratasóir ar mhaith leis go bhfanfá nó go dtabharfá cuntas fíorasach ar na comhráite a chuala tú.",
  "m2856": "Tairgeann tú fianaise agus tacaíocht gan an cinneadh faoin lóistín a ghlacadh ort féin.",
  "m2857": "Abair leis an iarratasóir gur ráthaíocht dó an t-árasán a fháil é teacht an Gharda ar an láthair.",
  "m2858": "Ní chinneann teacht an Gharda cé a gheobhaidh an tionóntacht ná toradh aon ghearáin comhionannais.",
  "m2859": "Mar an Garda a chonaic é seo, cé na nithe ar cheart duit a choinneáil ar leithligh?",
  "m2860": "Is foras cosanta i soláthar lóistín é cúnamh tithíochta. Ní deichiú foras uilíoch é a bhaineann le gach cinneadh póilíneachta. Is nithe ar leith iad diúltú an ghníomhaire agus freagra dímheasúil do chomhghleacaí. Déileáil le haon fhadhb iarbhír sábháilteachta nó iompair, éist leis an gcuntas agus cuir ráiteas do chomhghleacaí faoi cheist.",
  "m2861": "Cuir i gcoinne an ráitis, éist leis an gcuntas ar an méid a tharla agus déan idirdhealú idir an cheist lóistín agus aon cheist láithreach faoi iompar.",
  "m2862": "Cinntíonn tú go gcaitear leis an duine le meas arís, gan a mhaíomh go bhfuil sé de chumhacht agat tionónta a roghnú.",
  "m2863": "Glac leis gur leor é go bhfaigheann an duine HAP chun cuntas an ghníomhaire a chreidiúint gan éisteacht leis an iarratasóir.",
  "m2864": "Glacann an cur chuige sin leis an toimhde chéanna bunaithe ar stádas an duine, gan na fíricí a sheiceáil.",
  "m2865": "Dhá ábhar buartha, dhá bhealach éagsúla",
  "m2866": "Tá deireadh leis an achrann. Tá deimhniú na coinne féachana ag an iarratasóir. Fiafraíonn sé conas an diúltú agus ráiteas an Gharda a thuairisciú. Molann do chomhghleacaí gan a thaifeadadh ach go raibh an t-iarratasóir míshásta faoi árasán.",
  "m2867": "Conas a d’fhéadfá do ról mar fhinné agus na bealaí éagsúla chun gearán a dhéanamh a mhíniú?",
  "m2868": "Baineann treoir IHREC maidir le cóiríocht leis an diúltú an t-árasán a thaispeáint mar gheall ar HAP. Baineann treoir Fiosrú le gearán faoi iompar an Gharda aonair, lena n-áirítear gearán ó dhuine a chonaic an t-iompar go díreach. Is gnách go mbíonn toiliú an iarratasóra de dhíth chun gníomhú thar a cheann. Is ceist eile é do chuntas féin a thabhairt mar fhinné.",
  "m2869": "Déan idirdhealú idir an dá chomhrá. Treoraigh an duine chuig IHREC maidir leis an gcóiríocht agus chuig Fiosrú maidir le hiompar an Gharda.",
  "m2870": "Coinníonn tú taifead ar an dá cheist gan a thabhairt le tuiscint gur ionann gearán amháin a dhéanamh agus an gearán eile a dhéanamh leis.",
  "m2871": "Abair gur leor tuairisc amháin faoin árasán chun gearán a dhéanamh go huathoibríoch faoi iompar an Gharda freisin.",
  "m2872": "Tá bealaí ar leith ann chun ceist lóistín agus ceist faoi iompar Garda a ardú. Seiceáil an nós imeachta a bhaineann le gach ceann díobh.",
  "m2873": "Cad ba cheart a choinneáil sa taifead gairmiúil?",
  "m2874": "Taifead an chúis a thug an gníomhaire, mar a chuala tú féin í nó mar a tuairiscíodh duit í. Taifead focail do chomhghleacaí agus an t-iompar ar an láthair ar leithligh. Lean an nós imeachta cuí chun iompar do chomhghleacaí a thuairisciú. Is le lóistín go sonrach a bhaineann foras an chúnaimh tithíochta.",
  "m2875": "Tabhair cuntas cruinn ar an dá ábhar, luaigh foinse an eolais i ngach cás agus tarraing aird ar iompar do chomhghleacaí ar an mbealach cuí.",
  "m2876": "Coinníonn tú an fhianaise ábhartha agus is léir cé na ceisteanna éagsúla atá i gceist agus céard a bhaineann le gach ceann acu.",
  "m2877": "Ná taifead ach “iarratasóir míshásta” ós rud é go bhfuil deireadh leis an achrann.",
  "m2878": "Fágann an lipéad sin ar lár an chúis a tugadh leis an diúltú agus ráiteas an Gharda arbh fhinné thú air."
};
